-- [Migration: 20260523123000_secure_paystack_wallet_credit.sql]
-- -----------------------------------------------------------------------------
-- Move wallet crediting behind server-verified Paystack flows.

create or replace function public.increment_wallet_balance_admin(p_user_id uuid, p_amount numeric)
returns void
language plpgsql
security definer
set search_path to ''
as $$
begin
    if p_amount is null or p_amount <= 0 then
        raise exception 'Invalid amount';
    end if;

    insert into public.wallets (user_id, available_balance, total_earned)
    values (p_user_id, p_amount, p_amount)
    on conflict (user_id) do update
        set available_balance = public.wallets.available_balance + p_amount,
            total_earned = public.wallets.total_earned + p_amount,
            updated_at = now();
end;
$$;

revoke execute on function public.increment_wallet_balance(uuid, numeric) from public, anon, authenticated;
revoke execute on function public.increment_wallet_balance_admin(uuid, numeric) from public, anon, authenticated;


-- -----------------------------------------------------------------------------
-- [Migration: 20260523124500_money_rpc_auth_guards.sql]
-- -----------------------------------------------------------------------------
-- Ensure user-facing money RPCs can only act for the authenticated user.

create or replace function public.process_gift_purchase(
    p_sender_id uuid,
    p_receiver_id uuid,
    p_gift_id text
)
returns jsonb
language plpgsql
security definer
set search_path to ''
as $$
declare
    v_sender_wallet_id uuid;
    v_receiver_wallet_id uuid;
    v_gift_price numeric;
    v_gift_name text;
    v_sender_balance numeric;
begin
    if auth.uid() is null or auth.uid() <> p_sender_id then
        return jsonb_build_object('success', false, 'error', 'Not authorized');
    end if;

    select price, name into v_gift_price, v_gift_name
    from public.gifts
    where id = p_gift_id;

    if not found or v_gift_price is null or v_gift_price <= 0 then
        return jsonb_build_object('success', false, 'error', 'Invalid gift');
    end if;

    select id, available_balance into v_sender_wallet_id, v_sender_balance
    from public.wallets
    where user_id = p_sender_id
    for update;

    if v_sender_balance is null or v_sender_balance < v_gift_price then
        return jsonb_build_object('success', false, 'error', 'Insufficient balance');
    end if;

    select id into v_receiver_wallet_id
    from public.wallets
    where user_id = p_receiver_id;

    update public.wallets
    set available_balance = available_balance - v_gift_price,
        total_spent = total_spent + v_gift_price,
        updated_at = now()
    where id = v_sender_wallet_id;

    insert into public.wallet_transactions
        (user_id, wallet_id, type, amount, status, description, metadata)
    values
        (p_sender_id, v_sender_wallet_id, 'gift_purchase', v_gift_price, 'completed', 'Sent Gift: ' || v_gift_name, jsonb_build_object('receiver_id', p_receiver_id, 'gift_id', p_gift_id));

    if v_receiver_wallet_id is not null then
        update public.wallets
        set available_balance = available_balance + (v_gift_price * 0.5),
            total_earned = total_earned + (v_gift_price * 0.5),
            updated_at = now()
        where id = v_receiver_wallet_id;

        insert into public.wallet_transactions
            (user_id, wallet_id, type, amount, status, description, metadata)
        values
            (p_receiver_id, v_receiver_wallet_id, 'gift_received', (v_gift_price * 0.5), 'completed', 'Received Gift: ' || v_gift_name, jsonb_build_object('sender_id', p_sender_id, 'gift_id', p_gift_id));
    end if;

    return jsonb_build_object('success', true, 'new_balance', v_sender_balance - v_gift_price);
exception when others then
    return jsonb_build_object('success', false, 'error', sqlerrm);
end;
$$;

create or replace function public.process_gift_purchase(
    p_sender_id uuid,
    p_receiver_id uuid,
    p_gift_id uuid,
    p_amount numeric
)
returns jsonb
language plpgsql
security definer
set search_path to ''
as $$
declare
    v_balance numeric;
begin
    if auth.uid() is null or auth.uid() <> p_sender_id then
        return jsonb_build_object('success', false, 'error', 'Not authorized');
    end if;

    if p_amount is null or p_amount <= 0 then
        return jsonb_build_object('success', false, 'error', 'Invalid amount');
    end if;

    select available_balance into v_balance
    from public.wallets
    where user_id = p_sender_id
    for update;

    if v_balance is null or v_balance < p_amount then
        return jsonb_build_object('success', false, 'error', 'Insufficient balance');
    end if;

    update public.wallets
    set available_balance = available_balance - p_amount,
        total_spent = total_spent + p_amount,
        updated_at = now()
    where user_id = p_sender_id;

    update public.wallets
    set available_balance = available_balance + (p_amount * 0.8),
        total_earned = total_earned + (p_amount * 0.8),
        updated_at = now()
    where user_id = p_receiver_id;

    insert into public.transactions (user_id, amount, type, description, status, metadata)
    values (
        p_sender_id,
        p_amount,
        'gift',
        'Gift purchase',
        'completed',
        jsonb_build_object('gift_id', p_gift_id, 'receiver_id', p_receiver_id)
    )
    on conflict do nothing;

    return jsonb_build_object('success', true);
exception when others then
    return jsonb_build_object('success', false, 'error', sqlerrm);
end;
$$;

create or replace function public.process_pending_referral_funds(p_user_id uuid)
returns jsonb
language plpgsql
security definer
set search_path to ''
as $$
declare
    rec record;
    unlocked_amount numeric := 0;
begin
    if auth.uid() is null or auth.uid() <> p_user_id then
        return jsonb_build_object('success', false, 'error', 'Not authorized');
    end if;

    for rec in
        select id, amount, wallet_id
        from public.wallet_transactions
        where user_id = p_user_id
          and status = 'pending'
          and type = 'referral_bonus'
          and unlocks_at <= now()
    loop
        update public.wallet_transactions
        set status = 'completed',
            unlocks_at = null,
            description = 'Referral Reward (Unlocked)'
        where id = rec.id;

        update public.wallets
        set pending_balance = greatest(pending_balance - rec.amount, 0),
            available_balance = available_balance + rec.amount,
            total_earned = total_earned + rec.amount,
            updated_at = now()
        where id = rec.wallet_id;

        unlocked_amount := unlocked_amount + rec.amount;
    end loop;

    return jsonb_build_object('success', true, 'unlocked_total', unlocked_amount);
end;
$$;

create or replace function public.unlock_matured_rewards(p_user_id uuid)
returns jsonb
language plpgsql
security definer
set search_path to ''
as $$
declare
    rec record;
    unlocked_total numeric := 0;
begin
    if auth.uid() is null or auth.uid() <> p_user_id then
        return jsonb_build_object('success', false, 'error', 'Not authorized');
    end if;

    for rec in
        select id, amount, wallet_id
        from public.wallet_transactions
        where user_id = p_user_id
          and status = 'pending'
          and type = 'referral_bonus'
          and unlocks_at <= now()
    loop
        update public.wallet_transactions
        set status = 'completed',
            unlocks_at = null,
            description = replace(description, '(Locked 30 days)', '(Unlocked)')
        where id = rec.id;

        update public.wallets
        set pending_balance = greatest(coalesce(pending_balance, 0) - rec.amount, 0),
            available_balance = coalesce(available_balance, 0) + rec.amount,
            total_earned = coalesce(total_earned, 0) + rec.amount,
            updated_at = now()
        where id = rec.wallet_id;

        unlocked_total := unlocked_total + rec.amount;
    end loop;

    return jsonb_build_object('success', true, 'unlocked_amount', unlocked_total);
end;
$$;

create or replace function public.process_referral_milestones(p_referrer_id uuid)
returns jsonb
language plpgsql
security definer
set search_path to ''
as $$
declare
    v_count bigint;
    v_reward numeric := 0;
begin
    if auth.uid() is null or auth.uid() <> p_referrer_id then
        return jsonb_build_object('success', false, 'error', 'Not authorized');
    end if;

    select count(*) into v_count
    from public.referrals
    where referrer_id = p_referrer_id and status in ('pending', 'rewarded');

    if v_count > 0 and (v_count % 10) = 0 then
        v_reward := 3000;
        update public.wallets
        set available_balance = available_balance + v_reward,
            total_earned = total_earned + v_reward,
            updated_at = now()
        where user_id = p_referrer_id;
    end if;

    update public.referrals
    set status = 'rewarded', rewarded_at = now()
    where referrer_id = p_referrer_id and status = 'pending';

    return jsonb_build_object('referral_count', v_count, 'bonus_awarded', v_reward);
end;
$$;


-- -----------------------------------------------------------------------------
-- [Migration: 20260525213000_chat_media_disappearing_messages.sql]
-- -----------------------------------------------------------------------------
-- Chat hardening:
-- - Keep chat media private to match participants.
-- - Restore strict participant-only message inserts after the loose policy removal.
-- - Add per-match disappearing message settings.

alter table public.matches
add column if not exists disappearing_messages_seconds integer not null default 0;

alter table public.matches
drop constraint if exists matches_disappearing_messages_seconds_check;

alter table public.matches
add constraint matches_disappearing_messages_seconds_check
check (disappearing_messages_seconds in (0, 86400, 604800, 2592000));

alter table public.messages
add column if not exists expires_at timestamptz;

create index if not exists idx_messages_match_expires_at
on public.messages (match_id, expires_at);

create index if not exists idx_messages_expires_at
on public.messages (expires_at)
where expires_at is not null;

create or replace function public.set_message_expiry_from_match()
returns trigger
language plpgsql
set search_path to ''
as $$
declare
    v_seconds integer;
begin
    select disappearing_messages_seconds
    into v_seconds
    from public.matches
    where id = new.match_id;

    if coalesce(v_seconds, 0) > 0 and new.expires_at is null then
        new.expires_at := new.created_at + make_interval(secs => v_seconds);
    end if;

    return new;
end;
$$;

drop trigger if exists set_message_expiry_from_match on public.messages;
create trigger set_message_expiry_from_match
before insert on public.messages
for each row execute function public.set_message_expiry_from_match();

create or replace function public.update_match_disappearing_messages(
    p_match_id uuid,
    p_seconds integer
)
returns table(id uuid, disappearing_messages_seconds integer)
language plpgsql
security definer
set search_path to ''
as $$
begin
    if auth.uid() is null then
        raise exception 'Not authorized';
    end if;

    if p_seconds not in (0, 86400, 604800, 2592000) then
        raise exception 'Invalid disappearing message setting';
    end if;

    if not exists (
        select 1
        from public.matches m
        where m.id = p_match_id
          and auth.uid() in (m.user1_id, m.user2_id)
    ) then
        raise exception 'Not authorized';
    end if;

    update public.matches m
    set disappearing_messages_seconds = p_seconds
    where m.id = p_match_id
    returning m.id, m.disappearing_messages_seconds
    into id, disappearing_messages_seconds;

    return next;
end;
$$;

revoke execute on function public.update_match_disappearing_messages(uuid, integer) from public, anon;
grant execute on function public.update_match_disappearing_messages(uuid, integer) to authenticated;

