-- -----------------------------------------------------------------------------
-- [Migration: 20260706130000_leaderboard_and_wallet_fixes.sql]
-- -----------------------------------------------------------------------------
-- 1. DROP the existing view first
DROP VIEW IF EXISTS public.leaderboard_unified;

-- 2. CREATE or REPLACE the view with security_invoker = false (definer)
-- This runs the view with owner privileges, allowing users to query aggregated ranks 
-- across other users' swipes and wallets under Supabase RLS.
DROP VIEW IF EXISTS public.leaderboard_unified CASCADE;
CREATE VIEW public.leaderboard_unified WITH (security_invoker = false) AS
SELECT 
    p.id,
    p.full_name,
    p.avatar_url,
    p.university,
    p.gender,
    -- Composite "Most Wanted" score representing fans/engagement:
    -- 10 * right swipes received + 2 * profile views received + 5 * matches
    (
        COALESCE(swipe_stats.likes_received, 0) * 10 + 
        COALESCE(view_stats.views_received, 0) * 2 + 
        COALESCE(match_stats.match_count, 0) * 5
    )::integer as premium_swipes_received,
    COALESCE(w.total_spent, 0)::integer as total_spent,
    p.completion_score
FROM public.profiles p
LEFT JOIN (
    SELECT swiped_id, COUNT(id) as likes_received
    FROM public.swipes
    WHERE direction = 'right'
    GROUP BY swiped_id
) swipe_stats ON p.id = swipe_stats.swiped_id
LEFT JOIN (
    SELECT profile_owner_id, COUNT(id) as views_received
    FROM public.profile_views
    GROUP BY profile_owner_id
) view_stats ON p.id = view_stats.profile_owner_id
LEFT JOIN (
    SELECT user_id, COUNT(*) as match_count
    FROM (
        SELECT user1_id as user_id FROM public.matches
        UNION ALL
        SELECT user2_id as user_id FROM public.matches
    ) all_matches
    GROUP BY user_id
) match_stats ON p.id = match_stats.user_id
LEFT JOIN public.wallets w ON p.id = w.user_id
WHERE p.is_banned = false 
  AND p.is_shadow_banned = false
  -- Recency Filter: Only show users active in the last 14 days (or never-logged-in new users to avoid complete emptiness in testing)
  AND (
      p.last_active > (NOW() - INTERVAL '14 days') 
      OR p.last_seen_at > (NOW() - INTERVAL '14 days')
      OR p.last_active IS NULL
  );

-- 3. GRANT select rights on the new view
GRANT SELECT ON public.leaderboard_unified TO anon, authenticated;

-- 4. ONE-TIME CLEANUP: Recalculate total_spent for all existing wallets
-- First, sum up all completed payment/debit transactions from wallet_transactions
WITH spent_stats AS (
    SELECT 
        wallet_id, 
        COALESCE(SUM(amount), 0) as total_from_tx
    FROM 
        public.wallet_transactions
    WHERE 
        status IN ('completed', 'success')
        AND type IN ('payment', 'debit', 'subscription')
    GROUP BY 
        wallet_id
)
UPDATE public.wallets w
SET 
    total_spent = COALESCE(ss.total_from_tx, 0),
    updated_at = NOW()
FROM 
    spent_stats ss
WHERE 
    w.id = ss.wallet_id;

-- Second, add 2900 NGN for all users with active premium subscriptions 
-- to account for direct subscription payments that did not log wallet_transactions historically.
UPDATE public.wallets w
SET 
    total_spent = total_spent + 2900,
    updated_at = NOW()
FROM 
    public.subscriptions s
WHERE 
    w.user_id = s.user_id 
    AND s.status = 'active'
    AND NOT EXISTS (
        SELECT 1 
        FROM public.wallet_transactions wt 
        WHERE wt.wallet_id = w.id 
          AND wt.type = 'subscription' 
          AND wt.status IN ('completed', 'success')
    );


-- -----------------------------------------------------------------------------
-- [Migration: 20260707100000_referral_system_cleanup.sql]
-- -----------------------------------------------------------------------------
-- 1. Drop Duplicate Triggers on profiles
DROP TRIGGER IF EXISTS on_referred_profile_created ON public.profiles;
DROP TRIGGER IF EXISTS on_referred_profile_updated ON public.profiles;

-- 2. Drop Redundant Trigger Function
DROP FUNCTION IF EXISTS public.handle_referral_on_signup();

-- 3. Update process_referral_rewards to set pending_maturity_date
CREATE OR REPLACE FUNCTION public.process_referral_rewards()
RETURNS TRIGGER AS $$
DECLARE
    v_wallet_id UUID;
    v_referral_count INTEGER;
BEGIN
    -- 1. Award 3 free swipes to Referrer
    UPDATE public.profiles 
    SET free_swipes = COALESCE(free_swipes, 0) + 3
    WHERE id = NEW.referrer_id;

    -- 2. Award 20 free swipes to Referred User
    UPDATE public.profiles 
    SET free_swipes = GREATEST(COALESCE(free_swipes, 0), 20)
    WHERE id = NEW.referred_id;

    -- 3. Get Referrer's Wallet
    SELECT id INTO v_wallet_id FROM public.wallets WHERE user_id = NEW.referrer_id;

    IF v_wallet_id IS NOT NULL THEN
        -- 4. Create Pending Transaction for ₦500
        INSERT INTO public.wallet_transactions (
            user_id, wallet_id, type, amount, status, description, unlocks_at, reference_id
        ) VALUES (
            NEW.referrer_id,
            v_wallet_id,
            'referral_bonus',
            500.00,
            'pending',
            'Referral Reward (Locked 30 days)',
            now() + INTERVAL '30 days',
            'ref_' || NEW.referred_id
        );

        -- 5. Update Pending Balance & Maturity Date
        UPDATE public.wallets 
        SET pending_balance = COALESCE(pending_balance, 0) + 500.00,
            pending_maturity_date = CASE
                WHEN pending_maturity_date IS NULL OR pending_maturity_date < now()
                THEN now() + INTERVAL '30 days'
                ELSE pending_maturity_date
            END,
            updated_at = now()
        WHERE id = v_wallet_id;

        -- 6. Check for 10-Referral Milestone (₦3,000 bonus)
        SELECT COUNT(*) INTO v_referral_count 
        FROM public.referrals 
        WHERE referrer_id = NEW.referrer_id;

        IF v_referral_count > 0 AND (v_referral_count % 10) = 0 THEN
            INSERT INTO public.wallet_transactions (
                user_id, wallet_id, type, amount, status, description, unlocks_at, reference_id
            ) VALUES (
                NEW.referrer_id,
                v_wallet_id,
                'referral_bonus',
                3000.00,
                'pending',
                'Milestone Reward: 10 Referrals (Locked 30 days)',
                now() + INTERVAL '30 days',
                'milestone_' || v_referral_count || '_' || NEW.referrer_id
            );

            UPDATE public.wallets 
            SET pending_balance = COALESCE(pending_balance, 0) + 3000.00,
                pending_maturity_date = now() + INTERVAL '30 days',
                updated_at = now()
            WHERE id = v_wallet_id;
        END IF;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 4. Create trigger to auto-generate referral code on profiles BEFORE INSERT
DROP TRIGGER IF EXISTS on_profile_created_referral ON public.profiles;
CREATE TRIGGER on_profile_created_referral
    BEFORE INSERT ON public.profiles
    FOR EACH ROW EXECUTE FUNCTION handle_new_profile_referral();


