-- -----------------------------------------------------------------------------
-- [Migration: 20260715143000_admin_audit_view_and_user_status.sql]
-- -----------------------------------------------------------------------------
-- Admin audit visibility and reason-required user status changes.

create or replace function public.admin_set_user_status(
  p_user_id uuid,
  p_action text,
  p_status boolean,
  p_reason text
)
returns jsonb
language plpgsql
security definer
set search_path to ''
as $function$
declare
  v_action text := lower(trim(coalesce(p_action, '')));
  v_reason text := trim(coalesce(p_reason, ''));
  v_target public.profiles%rowtype;
  v_audit_action text;
begin
  if not public.is_app_admin() then
    raise exception 'Not authorized';
  end if;

  if auth.uid() = p_user_id and v_action in ('ban', 'shadow') and p_status is true then
    raise exception 'Admins cannot ban or shadow-ban themselves';
  end if;

  if v_action not in ('ban', 'shadow', 'verify') then
    raise exception 'Invalid user status action';
  end if;

  if length(v_reason) < 5 then
    raise exception 'Admin reason is required';
  end if;

  select *
  into v_target
  from public.profiles
  where id = p_user_id;

  if v_target.id is null then
    raise exception 'User profile not found';
  end if;

  if v_action = 'ban' then
    update public.profiles
    set is_banned = p_status
    where id = p_user_id;
    v_audit_action := case when p_status then 'admin_ban_user' else 'admin_unban_user' end;
  elsif v_action = 'shadow' then
    update public.profiles
    set is_shadow_banned = p_status
    where id = p_user_id;
    v_audit_action := case when p_status then 'admin_shadow_user' else 'admin_unshadow_user' end;
  else
    update public.profiles
    set is_verified = p_status
    where id = p_user_id;
    v_audit_action := case when p_status then 'admin_verify_user' else 'admin_unverify_user' end;
  end if;

  perform public.admin_write_audit_log(
    v_audit_action,
    'profile',
    p_user_id,
    jsonb_build_object(
      'status', p_status,
      'reason', v_reason,
      'target_email', v_target.email,
      'target_name', v_target.full_name
    )
  );

  return jsonb_build_object(
    'ok', true,
    'action', v_action,
    'status', p_status,
    'user_id', p_user_id
  );
end;
$function$;

create or replace function public.admin_get_audit_logs(
  p_limit integer default 100,
  p_offset integer default 0
)
returns table (
  id uuid,
  admin_user_id uuid,
  admin_email text,
  admin_name text,
  action text,
  target_type text,
  target_id uuid,
  metadata jsonb,
  created_at timestamp with time zone
)
language plpgsql
security definer
set search_path to ''
as $function$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 100), 1), 200);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
begin
  if not public.is_app_admin() then
    raise exception 'Not authorized';
  end if;

  return query
  select
    l.id,
    l.admin_user_id,
    coalesce(p.email, u.email)::text as admin_email,
    p.full_name::text as admin_name,
    l.action,
    l.target_type,
    l.target_id,
    l.metadata,
    l.created_at
  from public.admin_audit_logs l
  left join public.profiles p on p.id = l.admin_user_id
  left join auth.users u on u.id = l.admin_user_id
  order by l.created_at desc
  limit v_limit
  offset v_offset;
end;
$function$;

revoke all on function public.admin_set_user_status(uuid, text, boolean, text) from public, anon;
revoke all on function public.admin_get_audit_logs(integer, integer) from public, anon;

grant execute on function public.admin_set_user_status(uuid, text, boolean, text) to authenticated;
grant execute on function public.admin_get_audit_logs(integer, integer) to authenticated;


-- -----------------------------------------------------------------------------
-- [Migration: 20260715152000_offline_media_and_swipe_idempotency.sql]
-- -----------------------------------------------------------------------------
-- Offline-first payment safety foundation:
-- - Track paid swipe operation ids so reconnect retries are idempotent.
-- - Keep the existing 3-argument process_swipe_payment RPC working.

create table if not exists public.swipe_payment_operations (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles(id) on delete cascade,
  client_operation_id text not null,
  swipe_id uuid,
  swiped_id uuid not null references public.profiles(id) on delete cascade,
  swipe_type text not null,
  result jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, client_operation_id)
);

alter table public.swipe_payment_operations enable row level security;

drop policy if exists "Users can view own swipe payment operations" on public.swipe_payment_operations;
DROP POLICY IF EXISTS "Users can view own swipe payment operations" ON public.swipe_payment_operations;
create policy "Users can view own swipe payment operations"
  on public.swipe_payment_operations
  for select
  to authenticated
  using (user_id = (select auth.uid()));

revoke all on public.swipe_payment_operations from public, anon;
grant select on public.swipe_payment_operations to authenticated;
grant all on public.swipe_payment_operations to service_role;

create index if not exists idx_swipe_payment_operations_user_created
  on public.swipe_payment_operations(user_id, created_at desc);

drop function if exists public.process_swipe_payment(uuid, uuid, text, text);

create function public.process_swipe_payment(
  p_swiper_id uuid,
  p_swiped_id uuid,
  p_swipe_type text,
  p_client_operation_id text
)
returns jsonb
language plpgsql
security definer
set search_path to ''
as $$
declare
  v_cost numeric;
  v_swiper_wallet_id uuid;
  v_swiper_balance numeric;
  v_has_free_swipe boolean := false;
  v_is_premium boolean := false;
  v_swipe_id uuid;
  v_existing_result jsonb;
  v_result jsonb;
  v_operation_id text := nullif(trim(p_client_operation_id), '');
begin
  if auth.uid() is null or auth.uid() <> p_swiper_id then
    return jsonb_build_object('success', false, 'error', 'Not authorized');
  end if;

  if p_swipe_type not in ('standard', 'premium') then
    return jsonb_build_object('success', false, 'error', 'Invalid swipe type');
  end if;

  if v_operation_id is not null then
    insert into public.swipe_payment_operations (
      user_id,
      client_operation_id,
      swiped_id,
      swipe_type
    )
    values (
      p_swiper_id,
      v_operation_id,
      p_swiped_id,
      p_swipe_type
    )
    on conflict (user_id, client_operation_id) do nothing;

    select result
    into v_existing_result
    from public.swipe_payment_operations
    where user_id = p_swiper_id
      and client_operation_id = v_operation_id
    for update;

    if v_existing_result is not null then
      return v_existing_result || jsonb_build_object('idempotent', true);
    end if;
  end if;

  select id
  into v_swipe_id
  from public.swipes
  where swiper_id = p_swiper_id
    and swiped_id = p_swiped_id
  limit 1;

  select
    coalesce(p.is_premium, false)
    or exists (
      select 1
      from public.subscriptions s
      where s.user_id = p_swiper_id
        and s.plan_type = 'Premium'
        and s.status = 'active'
        and (s.current_period_end is null or s.current_period_end > now())
    )
  into v_is_premium
  from public.profiles p
  where p.id = p_swiper_id;

  if p_swipe_type = 'premium' then
    v_cost := 5000.00;
  else
    v_cost := 500.00;
  end if;

  if p_swipe_type = 'standard' and coalesce(v_is_premium, false) then
    update public.swipes
    set is_free = true
    where swiper_id = p_swiper_id
      and swiped_id = p_swiped_id
      and status = 'pending';

    v_result := jsonb_build_object('success', true, 'type', 'premium_free');
  elsif p_swipe_type = 'standard' then
    perform public.check_and_reset_swipe_limit(p_swiper_id);

    update public.profiles
    set free_swipes = greatest(coalesce(free_swipes, 0) - 1, 0)
    where id = p_swiper_id
      and coalesce(free_swipes, 0) > 0
    returning true into v_has_free_swipe;

    if v_has_free_swipe then
      update public.swipes
      set is_free = true
      where swiper_id = p_swiper_id
        and swiped_id = p_swiped_id
        and status = 'pending';

      v_result := jsonb_build_object('success', true, 'type', 'free');
    end if;
  end if;

  if v_result is null then
    select id, available_balance
    into v_swiper_wallet_id, v_swiper_balance
    from public.wallets
    where user_id = p_swiper_id
    for update;

    if v_swiper_wallet_id is null or coalesce(v_swiper_balance, 0) < v_cost then
      v_result := jsonb_build_object('success', false, 'error', 'Insufficient balance');
    else
      update public.wallets
      set available_balance = available_balance - v_cost,
          total_spent = coalesce(total_spent, 0) + v_cost,
          updated_at = now()
      where id = v_swiper_wallet_id;

      insert into public.wallet_transactions (
        user_id,
        wallet_id,
        type,
        amount,
        status,
        description,
        reference_id,
        metadata
      )
      values (
        p_swiper_id,
        v_swiper_wallet_id,
        'swipe_purchase',
        v_cost,
        'completed',
        upper(p_swipe_type) || ' Swipe Request',
        case when v_operation_id is null then null else 'swipe:' || v_operation_id end,
        jsonb_build_object(
          'target_id', p_swiped_id,
          'swipe_id', v_swipe_id,
          'swipe_type', p_swipe_type,
          'client_operation_id', v_operation_id
        )
      );

      v_result := jsonb_build_object('success', true, 'type', 'paid', 'amount', v_cost);
    end if;
  end if;

  if v_operation_id is not null and coalesce((v_result->>'success')::boolean, false) then
    update public.swipe_payment_operations
    set swipe_id = v_swipe_id,
        result = v_result,
        updated_at = now()
    where user_id = p_swiper_id
      and client_operation_id = v_operation_id;
  elsif v_operation_id is not null then
    delete from public.swipe_payment_operations
    where user_id = p_swiper_id
      and client_operation_id = v_operation_id;
  end if;

  return v_result;
exception when others then
  v_result := jsonb_build_object('success', false, 'error', sqlerrm);

  if v_operation_id is not null then
    delete from public.swipe_payment_operations
    where user_id = p_swiper_id
      and client_operation_id = v_operation_id;
  end if;

  return v_result;
end;
$$;

