create or replace function public.admin_search_users(
  p_limit integer default 50,
  p_offset integer default 0,
  p_query text default null,
  p_status text default null,
  p_gender text default null,
  p_university text default null,
  p_verified boolean default null,
  p_premium boolean default null
)
returns table (
  id uuid,
  full_name text,
  email text,
  gender text,
  university text,
  avatar_url text,
  is_banned boolean,
  is_shadow_banned boolean,
  is_verified boolean,
  is_premium boolean,
  created_at timestamp with time zone,
  last_seen_at timestamp with time zone,
  last_active timestamp with time zone,
  total_count bigint
)
language plpgsql
security definer
set search_path to ''
as $function$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 200);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_query text := nullif(trim(coalesce(p_query, '')), '');
  v_status text := lower(nullif(trim(coalesce(p_status, '')), ''));
  v_gender text := lower(nullif(trim(coalesce(p_gender, '')), ''));
  v_university text := nullif(trim(coalesce(p_university, '')), '');
begin
  if not (public.admin_has_permission('users:read') or public.admin_has_permission('users:moderate')) then
    raise exception 'Not authorized';
  end if;

  if v_status is not null and v_status not in ('active', 'banned', 'shadow') then
    raise exception 'Invalid status filter';
  end if;

  return query
  with filtered as (
    select p.*
    from public.profiles p
    where
      (
        v_query is null
        or coalesce(p.full_name, '') ilike '%' || v_query || '%'
        or coalesce(p.email, '') ilike '%' || v_query || '%'
        or p.id::text = v_query
      )
      and (
        v_status is null
        or (v_status = 'banned' and coalesce(p.is_banned, false))
        or (v_status = 'shadow' and coalesce(p.is_shadow_banned, false))
        or (
          v_status = 'active'
          and not coalesce(p.is_banned, false)
          and not coalesce(p.is_shadow_banned, false)
        )
      )
      and (v_gender is null or lower(coalesce(p.gender, '')) = v_gender)
      and (v_university is null or coalesce(p.university, '') ilike '%' || v_university || '%')
      and (p_verified is null or coalesce(p.is_verified, false) = p_verified)
      and (p_premium is null or coalesce(p.is_premium, false) = p_premium)
  )
  select
    f.id,
    f.full_name::text,
    f.email::text,
    f.gender::text,
    f.university::text,
    f.avatar_url::text,
    coalesce(f.is_banned, false),
    coalesce(f.is_shadow_banned, false),
    coalesce(f.is_verified, false),
    coalesce(f.is_premium, false),
    f.created_at,
    f.last_seen_at,
    f.last_active,
    count(*) over()::bigint as total_count
  from filtered f
  order by f.created_at desc nulls last
  limit v_limit
  offset v_offset;
end;
$function$;

create or replace function public.admin_get_user_detail(p_user_id uuid)
returns jsonb
language plpgsql
security definer
set search_path to ''
as $function$
declare
  v_profile jsonb;
  v_wallet jsonb;
  v_transactions jsonb;
begin
  if not (public.admin_has_permission('users:read') or public.admin_has_permission('users:moderate')) then
    raise exception 'Not authorized';
  end if;

  select to_jsonb(p)
  into v_profile
  from (
    select
      id,
      email,
      full_name,
      university,
      gender,
      avatar_url,
      is_banned,
      is_shadow_banned,
      is_verified,
      is_premium,
      premium_expires_at,
      created_at,
      last_seen_at,
      last_active
    from public.profiles
    where id = p_user_id
  ) p;

  select to_jsonb(w)
  into v_wallet
  from (
    select
      id,
      user_id,
      available_balance,
      pending_balance,
      total_earned,
      total_spent,
      total_withdrawn,
      updated_at
    from public.wallets
    where user_id = p_user_id
  ) w;

  select coalesce(jsonb_agg(to_jsonb(t) order by t.created_at desc), '[]'::jsonb)
  into v_transactions
  from (
    select
      id,
      user_id,
      wallet_id,
      type,
      amount,
      status,
      description,
      payment_method,
      reference_id,
      created_at
    from public.wallet_transactions
    where user_id = p_user_id
    order by created_at desc
    limit 20
  ) t;

  perform public.admin_write_audit_log(
    'admin_view_user_detail',
    'profile',
    p_user_id,
    jsonb_build_object('transaction_limit', 20)
  );

  return jsonb_build_object(
    'profile', coalesce(v_profile, '{}'::jsonb),
    'wallet', v_wallet,
    'transactions', v_transactions
  );
end;
$function$;

create or replace function public.admin_get_confessions(
  p_limit integer default 50,
  p_offset integer default 0,
  p_search text default null,
  p_university text default null,
  p_from timestamp with time zone default null,
  p_to timestamp with time zone default null
)
returns table (
  id uuid,
  content text,
  university text,
