      )
      and (p_from is null or r.created_at >= p_from)
      and (p_to is null or r.created_at <= p_to)
  )
  select
    f.id,
    f.confession_id,
    f.reporter_id,
    f.reason::text,
    f.details::text,
    f.status::text,
    f.created_at,
    f.confession_content::text,
