create or replace function public.get_native_messages(
    p_match_id uuid,
    p_before timestamptz default null,
    p_limit integer default 50
)
returns table(
    id uuid,
    match_id uuid,
    sender_id uuid,
    content text,
    type text,
    is_read boolean,
    created_at timestamptz,
    read_at timestamptz,
    expires_at timestamptz
)
language plpgsql
stable
security definer
set search_path to ''
as $$
declare
    v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 100);
begin
    if auth.uid() is null then
        raise exception 'not_authenticated';
    end if;

    if not private.is_match_participant(p_match_id) then
        raise exception 'not_authorized';
    end if;

    return query
    select page.id,
           page.match_id,
           page.sender_id,
           page.content,
           page.type,
           page.is_read,
           page.created_at,
           page.read_at,
           page.expires_at
    from (
        select msg.id,
               msg.match_id,
               msg.sender_id,
               msg.content,
               coalesce(msg.type, 'text') as type,
               coalesce(msg.is_read, false) as is_read,
               msg.created_at,
               msg.read_at,
               msg.expires_at
        from public.messages msg
        where msg.match_id = p_match_id
          and (p_before is null or msg.created_at < p_before)
          and (msg.expires_at is null or msg.expires_at > now())
        order by msg.created_at desc, msg.id desc
        limit v_limit
    ) page
    order by page.created_at, page.id;
end;
$$;

