-- -----------------------------------------------------------------------------
-- [Migration: 20260904100000_audit_remediation_core.sql]
-- -----------------------------------------------------------------------------
-- Migration: 20260904100000_audit_remediation_core.sql
-- Purpose:
-- 1. Harmonize process_swipe_payment with public.swipe_limits (20 free daily swipes)
-- 2. Strengthen admin_update_admin_access owner protection and remove wildcard permissions for legacy admin

CREATE OR REPLACE FUNCTION public.process_swipe_payment(
  p_swiper_id uuid,
  p_swiped_id uuid,
  p_swipe_type text,
  p_client_operation_id text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
declare
  v_cost numeric;
  v_swiper_wallet_id uuid;
  v_swiper_balance numeric;
  v_has_free_swipe boolean := false;
  v_is_premium boolean := false;
  v_swipe_id uuid;
  v_existing_result jsonb;
  v_result jsonb;
  v_operation_id text := nullif(trim(p_client_operation_id), '');
  v_swipes_used int;
begin
  if auth.uid() is null or auth.uid() <> p_swiper_id then
    return jsonb_build_object('success', false, 'error', 'Not authorized');
  end if;

  if p_swipe_type not in ('standard', 'premium') then
    return jsonb_build_object('success', false, 'error', 'Invalid swipe type');
  end if;

  if v_operation_id is not null then
    insert into public.swipe_payment_operations (
      user_id,
      client_operation_id,
      swiped_id,
      swipe_type
    )
    values (
      p_swiper_id,
      v_operation_id,
      p_swiped_id,
      p_swipe_type
    )
    on conflict (user_id, client_operation_id) do nothing;

    select result
    into v_existing_result
    from public.swipe_payment_operations
    where user_id = p_swiper_id
      and client_operation_id = v_operation_id
    for update;

    if v_existing_result is not null then
      return v_existing_result || jsonb_build_object('idempotent', true);
    end if;
  end if;

  select id
  into v_swipe_id
  from public.swipes
  where swiper_id = p_swiper_id
    and swiped_id = p_swiped_id
  limit 1;

  select
    coalesce(p.is_premium, false)
    or exists (
      select 1
      from public.subscriptions s
      where s.user_id = p_swiper_id
        and s.plan_type = 'Premium'
        and s.status = 'active'
        and (s.current_period_end is null or s.current_period_end > now())
    )
  into v_is_premium
  from public.profiles p
  where p.id = p_swiper_id;

  if p_swipe_type = 'premium' then
    v_cost := 5000.00;
  else
    v_cost := 500.00;
  end if;

  if p_swipe_type = 'standard' and coalesce(v_is_premium, false) then
    update public.swipes
    set is_free = true
    where swiper_id = p_swiper_id
      and swiped_id = p_swiped_id
      and status = 'pending';

    v_result := jsonb_build_object('success', true, 'type', 'premium_free');
  elsif p_swipe_type = 'standard' then
    -- Reset or initialize daily swipe limit
    perform public.check_and_reset_swipe_limit(p_swiper_id);

    -- Check if daily free swipes (limit of 20) are available
    select swipes_used into v_swipes_used
    from public.swipe_limits
    where user_id = p_swiper_id
    for update;

    if coalesce(v_swipes_used, 0) < 20 then
      update public.swipe_limits
      set swipes_used = coalesce(swipes_used, 0) + 1
      where user_id = p_swiper_id;

      update public.swipes
      set is_free = true
      where swiper_id = p_swiper_id
        and swiped_id = p_swiped_id
        and status = 'pending';

      v_result := jsonb_build_object('success', true, 'type', 'free', 'used_count', coalesce(v_swipes_used, 0) + 1, 'max_count', 20);
    else
      -- Check if user has bonus free swipes stored on profile
      update public.profiles
      set free_swipes = greatest(coalesce(free_swipes, 0) - 1, 0)
      where id = p_swiper_id
        and coalesce(free_swipes, 0) > 0
      returning true into v_has_free_swipe;

      if v_has_free_swipe then
        update public.swipes
        set is_free = true
        where swiper_id = p_swiper_id
          and swiped_id = p_swiped_id
          and status = 'pending';

        v_result := jsonb_build_object('success', true, 'type', 'free');
      end if;
    end if;
  end if;

  if v_result is null then
    select id, available_balance
    into v_swiper_wallet_id, v_swiper_balance
    from public.wallets
    where user_id = p_swiper_id
    for update;

    if v_swiper_wallet_id is null or coalesce(v_swiper_balance, 0) < v_cost then
      v_result := jsonb_build_object('success', false, 'error', 'Insufficient balance');
    else
      update public.wallets
      set available_balance = available_balance - v_cost,
          total_spent = coalesce(total_spent, 0) + v_cost,
          updated_at = now()
      where id = v_swiper_wallet_id;

      insert into public.wallet_transactions (
        user_id,
        wallet_id,
        type,
        amount,
        status,
        description,
        reference_id,
        metadata
      )
      values (
        p_swiper_id,
        v_swiper_wallet_id,
        'swipe_purchase',
        v_cost,
        'completed',
        upper(p_swipe_type) || ' Swipe Request',
        case when v_operation_id is null then null else 'swipe:' || v_operation_id end,
        jsonb_build_object(
          'target_id', p_swiped_id,
          'swipe_id', v_swipe_id,
          'swipe_type', p_swipe_type,
          'client_operation_id', v_operation_id
        )
      );

      v_result := jsonb_build_object('success', true, 'type', 'paid', 'amount', v_cost);
    end if;
  end if;

  if v_operation_id is not null and coalesce((v_result->>'success')::boolean, false) then
    update public.swipe_payment_operations
    set swipe_id = v_swipe_id,
        result = v_result,
        updated_at = now()
    where user_id = p_swiper_id
      and client_operation_id = v_operation_id;
  elsif v_operation_id is not null then
    delete from public.swipe_payment_operations
    where user_id = p_swiper_id
      and client_operation_id = v_operation_id;
  end if;

  return v_result;
exception when others then
  v_result := jsonb_build_object('success', false, 'error', sqlerrm);

  if v_operation_id is not null then
    delete from public.swipe_payment_operations
    where user_id = p_swiper_id
      and client_operation_id = v_operation_id;
  end if;

  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.process_swipe_payment(
  p_swiper_id uuid,
  p_swiped_id uuid,
  p_swipe_type text
)
RETURNS jsonb
LANGUAGE sql
SECURITY DEFINER
SET search_path TO ''
AS $function$
  select public.process_swipe_payment(p_swiper_id, p_swiped_id, p_swipe_type, null::text);
$function$;

-- Update admin_update_admin_access with strict Super Admin protection
CREATE OR REPLACE FUNCTION public.admin_update_admin_access(
  p_target_user_id uuid,
  p_mode text,
  p_permissions text[] default '{}'::text[],
  p_reason text default null
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
declare
  v_mode text := lower(nullif(trim(coalesce(p_mode, '')), ''));
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_target auth.users;
  v_target_email text;
  v_permissions text[];
  v_permission text;
  v_allowed text[] := array[
    'users:read',
    'users:moderate',
    'content:moderate',
    'finance:read',
    'finance:payouts',
    'config:write',
    'promo:write',
    'push:broadcast',
    'audit:read'
  ];
  v_metadata jsonb;
begin
  if not public.admin_is_owner() then
    raise exception 'Not authorized';
  end if;

  if p_target_user_id is null then
    raise exception 'Target user is required';
  end if;

  if v_mode not in ('legacy_admin', 'restricted_admin', 'revoke_admin') then
    raise exception 'Unsupported admin access mode';
  end if;

  if v_reason is null or length(v_reason) < 5 then
    raise exception 'Audit reason must be at least 5 characters';
  end if;

  select *
  into v_target
  from auth.users
  where id = p_target_user_id;

  if v_target.id is null then
    raise exception 'Target user not found';
  end if;

  v_target_email := lower(coalesce(v_target.email, ''));

  -- Super Admin / Owner accounts are completely immutable via this RPC
  if v_target_email in ('godwillgodslife@gmail.com', 'godswillgodwillgodlife@gmail.com') then
    raise exception 'Owner admin access cannot be modified or revoked';
  end if;

  if v_mode = 'restricted_admin' then
    select coalesce(array_agg(distinct lower(trim(permission))) filter (where nullif(trim(permission), '') is not null), '{}'::text[])
    into v_permissions
    from unnest(coalesce(p_permissions, '{}'::text[])) as permissions(permission);

    if coalesce(array_length(v_permissions, 1), 0) = 0 then
      raise exception 'Restricted admins require at least one permission';
    end if;

    foreach v_permission in array v_permissions loop
      if not v_permission = any(v_allowed) then
        raise exception 'Unsupported permission: %', v_permission;
      end if;
    end loop;

    update auth.users
    set raw_app_meta_data = jsonb_strip_nulls(
      (coalesce(raw_app_meta_data, '{}'::jsonb) - 'is_admin')
      || jsonb_build_object(
        'role', 'restricted_admin',
        'admin_permissions', to_jsonb(v_permissions)
      )
    )
    where id = p_target_user_id;
  elsif v_mode = 'legacy_admin' then
    -- Explicit standard operational permissions, never wildcard
    v_permissions := array[
      'users:read', 'users:moderate',
      'content:moderate',
      'finance:read',
      'promo:write',
      'push:broadcast',
      'audit:read'
    ];

    update auth.users
    set raw_app_meta_data = jsonb_strip_nulls(
      (coalesce(raw_app_meta_data, '{}'::jsonb) - 'admin_permissions')
      || jsonb_build_object(
        'is_admin', true,
        'role', 'admin',
        'admin_permissions', to_jsonb(v_permissions)
      )
    )
    where id = p_target_user_id;
  elsif v_mode = 'revoke_admin' then
    v_permissions := '{}'::text[];

    update auth.users
    set raw_app_meta_data = jsonb_strip_nulls(
      coalesce(raw_app_meta_data, '{}'::jsonb)
      - 'is_admin'
      - 'role'
      - 'admin_permissions'
    )
    where id = p_target_user_id;
  end if;

  v_metadata := jsonb_build_object(
    'mode', v_mode,
    'permissions', to_jsonb(v_permissions),
    'reason', v_reason,
    'target_email', v_target.email
  );

  perform public.admin_write_audit_log(
    'admin_update_admin_access',
    'admin_access',
    p_target_user_id,
    v_metadata
  );

  return jsonb_build_object(
    'success', true,
    'target_user_id', p_target_user_id,
    'target_email', v_target.email,
    'mode', v_mode,
    'permissions', to_jsonb(v_permissions)
  );
end;
$function$;


-- -----------------------------------------------------------------------------
-- [Migration: 20260904120000_fix_onboarding_profile_permissions.sql]
-- -----------------------------------------------------------------------------
-- Migration: Fix Onboarding Profile Permissions and RPC
-- 1. Ensure update_photo_timestamp is SECURITY DEFINER with safe search_path
CREATE OR REPLACE FUNCTION public.update_photo_timestamp()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_catalog
AS $$
BEGIN
    -- 1. If profile_photos[1] is set and distinct from old profile_photos[1], sync avatar_url
    IF NEW.profile_photos IS NOT NULL AND array_length(NEW.profile_photos, 1) > 0 THEN
        IF OLD.profile_photos IS NULL 
           OR array_length(OLD.profile_photos, 1) = 0 
           OR NEW.profile_photos[1] IS DISTINCT FROM OLD.profile_photos[1] THEN
            IF NEW.profile_photos[1] IS NOT NULL AND btrim(NEW.profile_photos[1]) <> '' THEN
                NEW.avatar_url := NEW.profile_photos[1];
            END IF;
        END IF;
    END IF;

    -- 2. If avatar_url was empty or null, fallback to profile_photos[1]
    IF COALESCE(NEW.avatar_url, '') = '' AND NEW.profile_photos IS NOT NULL AND array_length(NEW.profile_photos, 1) > 0 THEN
        NEW.avatar_url := NEW.profile_photos[1];
    END IF;

    -- 3. Update photo_updated_at if any photo field changed
    IF NEW.avatar_url IS DISTINCT FROM OLD.avatar_url
       OR NEW.photos IS DISTINCT FROM OLD.photos
       OR NEW.profile_photos IS DISTINCT FROM OLD.profile_photos THEN
        NEW.photo_updated_at := NOW();
    END IF;

    RETURN NEW;
END;
$$;

-- 2. Ensure table-level permissions for authenticated users on public.profiles
GRANT USAGE ON SCHEMA public TO authenticated;
GRANT SELECT, INSERT, UPDATE ON TABLE public.profiles TO authenticated;

-- 3. Dedicated SECURITY DEFINER onboarding completion RPC function
CREATE OR REPLACE FUNCTION public.complete_user_onboarding(
    p_full_name TEXT DEFAULT NULL,
    p_age INTEGER DEFAULT NULL,
    p_university TEXT DEFAULT NULL,
    p_level TEXT DEFAULT NULL,
    p_interests JSONB DEFAULT NULL,
    p_attraction_goal TEXT DEFAULT NULL,
    p_profile_photos TEXT[] DEFAULT NULL,
    p_avatar_url TEXT DEFAULT NULL
)
RETURNS public.profiles
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_catalog
AS $$
DECLARE
    v_user_id UUID;
    v_profile public.profiles;
    v_avatar TEXT;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
    END IF;

    IF p_age IS NOT NULL AND p_age < 18 THEN
        RAISE EXCEPTION 'You must be at least 18 years old to use College Date.' USING ERRCODE = '22023';
    END IF;

    -- Determine avatar URL
    v_avatar := COALESCE(NULLIF(p_avatar_url, ''), (p_profile_photos)[1]);

    -- Ensure profile exists (if trigger hadn't fired or profile missing)
    INSERT INTO public.profiles (
        id,
        email,
        full_name,
        gender,
        age,
        university,
        role,
        free_swipes,
        is_onboarded
    )
    SELECT
        u.id,
        COALESCE(u.email, ''),
        COALESCE(p_full_name, u.raw_user_meta_data->>'full_name', 'Student'),
        LOWER(COALESCE(u.raw_user_meta_data->>'role', 'male')),
        COALESCE(p_age, 19),
        COALESCE(p_university, 'Campus'),
        INITCAP(COALESCE(u.raw_user_meta_data->>'role', 'Male')),
        20,
        false
    FROM auth.users u
    WHERE u.id = v_user_id
    ON CONFLICT (id) DO NOTHING;

    -- Update profile
    UPDATE public.profiles
    SET
        full_name = COALESCE(NULLIF(p_full_name, ''), full_name),
        age = COALESCE(p_age, age),
        university = COALESCE(NULLIF(p_university, ''), university),
        level = COALESCE(NULLIF(p_level, ''), level),
        interests = COALESCE(p_interests, interests),
        attraction_goal = COALESCE(NULLIF(p_attraction_goal, ''), attraction_goal),
        profile_photos = COALESCE(p_profile_photos, profile_photos),
        avatar_url = COALESCE(v_avatar, avatar_url),
        is_onboarded = true,
        updated_at = NOW()
    WHERE id = v_user_id
    RETURNING * INTO v_profile;

    RETURN v_profile;
END;
$$;

-- 4. Grant execute permission on the RPC to authenticated users
GRANT EXECUTE ON FUNCTION public.complete_user_onboarding(
    TEXT, INTEGER, TEXT, TEXT, JSONB, TEXT, TEXT[], TEXT
) TO authenticated;


-- -----------------------------------------------------------------------------
-- [Migration: 20260904190000_freemium_requests_and_account_lifecycle.sql]
-- -----------------------------------------------------------------------------
-- Migration: 20260904190000_freemium_requests_and_account_lifecycle.sql
-- Enables 3 daily free request accepts for freemium users and adds account deactivation / deletion RPCs.

create or replace function public.get_admirers_secure(p_limit integer default 50)
returns jsonb
language plpgsql
security definer
set search_path to ''
as $$
declare
    v_user_id uuid := auth.uid();
    v_is_premium boolean;
    v_total integer;
    v_today_accepts_count integer;
    v_free_accepts_remaining integer;
    v_items jsonb;
begin
    if v_user_id is null then
        return jsonb_build_object('success', false, 'error', 'Not authenticated');
    end if;

    v_is_premium := public.has_entitlement(v_user_id, 'see_admirers')
        or public.has_entitlement(v_user_id, 'premium');

    -- Count total pending swipes targeting the user
    select count(*)::integer
    into v_total
    from public.swipes sw
    where sw.swiped_id = v_user_id
      and sw.status = 'pending';

    -- Count how many requests the user has accepted today (UTC)
    select count(*)::integer
    into v_today_accepts_count
    from public.swipes sw
    where sw.swiped_id = v_user_id
      and sw.status = 'accepted'
      and sw.updated_at >= (current_date at time zone 'UTC');

    if v_is_premium then
        v_free_accepts_remaining := 999;
    else
        v_free_accepts_remaining := greatest(0, 3 - v_today_accepts_count);
    end if;

    if not v_is_premium then
        -- For freemium users, unlock up to 3 admirers so they can accept/decline them, lock the rest
        select coalesce(jsonb_agg(item), '[]'::jsonb)
        into v_items
        from (
            select
                case
                    when row_number() over (order by coalesce(sw.is_priority, false) desc, sw.created_at desc) <= 3 then
                        jsonb_build_object(
                            'id', sw.id,
                            'swiper_id', sw.swiper_id,
                            'swiped_id', sw.swiped_id,
                            'type', sw.type,
                            'status', sw.status,
                            'is_priority', coalesce(sw.is_priority, false),
                            'message_teaser', sw.message_teaser,
                            'created_at', sw.created_at,
                            'locked', false,
                            'swiper', to_jsonb(p)
                        )
                    else
                        jsonb_build_object(
                            'created_at', sw.created_at,
                            'is_priority', coalesce(sw.is_priority, false),
                            'locked', true
                        )
                end as item
            from public.swipes sw
            join public.profiles p on p.id = sw.swiper_id
            where sw.swiped_id = v_user_id
              and sw.status = 'pending'
            order by coalesce(sw.is_priority, false) desc, sw.created_at desc
            limit greatest(1, least(coalesce(p_limit, 50), 100))
        ) locked_items;

        return jsonb_build_object(
            'success', true,
            'premium', false,
            'upgrade_required', v_total > 3 or v_free_accepts_remaining = 0,
            'total_count', v_total,
            'today_accepts_count', v_today_accepts_count,
            'free_accepts_remaining', v_free_accepts_remaining,
            'daily_limit', 3,
            'items', coalesce(v_items, '[]'::jsonb)
        );
    end if;

    -- Premium user: return all admirers fully unlocked
    select coalesce(jsonb_agg(item), '[]'::jsonb)
    into v_items
    from (
        select jsonb_build_object(
            'id', sw.id,
            'swiper_id', sw.swiper_id,
            'swiped_id', sw.swiped_id,
            'type', sw.type,
            'status', sw.status,
            'is_priority', coalesce(sw.is_priority, false),
            'message_teaser', sw.message_teaser,
            'created_at', sw.created_at,
            'locked', false,
            'swiper', to_jsonb(p)
        ) as item
        from public.swipes sw
        join public.profiles p on p.id = sw.swiper_id
        where sw.swiped_id = v_user_id
          and sw.status = 'pending'
        order by coalesce(sw.is_priority, false) desc, sw.created_at desc
        limit greatest(1, least(coalesce(p_limit, 50), 100))
    ) unlocked_items;

    return jsonb_build_object(
        'success', true,
        'premium', true,
        'upgrade_required', false,
        'total_count', v_total,
        'today_accepts_count', v_today_accepts_count,
        'free_accepts_remaining', 999,
        'daily_limit', 999,
        'items', coalesce(v_items, '[]'::jsonb)
    );
end;
$$;

grant execute on function public.get_admirers_secure(integer) to authenticated;

-- Hardened accept_swipe_request with 3 free daily accepts check for freemium
create or replace function public.accept_swipe_request(p_swipe_id uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path to ''
as $$
declare
    v_user_id uuid := auth.uid();
    v_swiper_id uuid;
    v_swiped_id uuid;
    v_match_id uuid;
    v_participants uuid[];
    v_is_premium boolean;
    v_today_accepts_count integer;
begin
    if v_user_id is null then
        return jsonb_build_object('success', false, 'error', 'not_authenticated');
    end if;

    -- Check if swipe exists, belongs to caller, and is pending
    select s.swiper_id, s.swiped_id
    into v_swiper_id, v_swiped_id
    from public.swipes s
    where s.id = p_swipe_id
      and s.swiped_id = v_user_id
      and s.direction = 'right'
      and s.status = 'pending'
    for update;

    if not found then
        return jsonb_build_object('success', false, 'error', 'request_not_found_or_unauthorized');
    end if;

    -- Check user premium status
    v_is_premium := public.has_entitlement(v_user_id, 'premium');

    -- If not premium, verify daily quota of 3 free accepts
    if not v_is_premium then
        select count(*)::integer
        into v_today_accepts_count
        from public.swipes sw
        where sw.swiped_id = v_user_id
          and sw.status = 'accepted'
          and sw.updated_at >= (current_date at time zone 'UTC');

        if v_today_accepts_count >= 3 then
            return jsonb_build_object(
                'success', false,
                'error', 'daily_limit_reached',
                'message', 'You have used your 3 free accepts for today. Upgrade to Premium for unlimited accepts!'
            );
        end if;
    end if;

    -- Accept swipe
    update public.swipes
    set status = 'accepted',
        updated_at = now()
    where id = p_swipe_id;

    v_participants := array[least(v_swiper_id, v_swiped_id), greatest(v_swiper_id, v_swiped_id)]::uuid[];

    insert into public.matches (user1_id, user2_id, user_ids, created_at)
    values (v_participants[1], v_participants[2], v_participants, now())
    on conflict (user1_id, user2_id) do update
    set user_ids = excluded.user_ids
    returning id into v_match_id;

    return jsonb_build_object(
        'success', true,
        'match_id', v_match_id,
        'remaining_accepts', case when v_is_premium then 999 else greatest(0, 2 - coalesce(v_today_accepts_count, 0)) end
    );
exception when others then
    return jsonb_build_object('success', false, 'error', sqlerrm);
end;
$$;

grant execute on function public.accept_swipe_request(uuid) to authenticated;

-- Deactivate User Account RPC
create or replace function public.deactivate_user_account()
returns jsonb
language plpgsql
security definer
set search_path to ''
as $$
declare
    v_user_id uuid := auth.uid();
begin
    if v_user_id is null then
        return jsonb_build_object('success', false, 'error', 'not_authenticated');
    end if;

    update public.profiles
    set incognito_mode = true,
        is_online = false,
        status_text = 'deactivated',
        updated_at = now()
    where id = v_user_id;

    return jsonb_build_object('success', true, 'message', 'Account deactivated successfully');
end;
$$;

grant execute on function public.deactivate_user_account() to authenticated;

-- Delete User Account RPC (Data Safety compliance)
create or replace function public.delete_user_account()
returns jsonb
language plpgsql
security definer
set search_path to ''
as $$
declare
    v_user_id uuid := auth.uid();
begin
    if v_user_id is null then
        return jsonb_build_object('success', false, 'error', 'not_authenticated');
    end if;

    -- Anonymize and disable profile
    update public.profiles
    set full_name = 'Deleted Account',
        username = 'deleted_' || substr(v_user_id::text, 1, 8),
        bio = 'This account has been deleted.',
        avatar_url = null,
        profile_photos = '{}',
        phone = null,
        incognito_mode = true,
        is_banned = true,
        is_online = false,
        status_text = 'deleted',
        updated_at = now()
    where id = v_user_id;

    -- Clean up pending requests
    delete from public.swipes
    where swiped_id = v_user_id and status = 'pending';

    return jsonb_build_object('success', true, 'message', 'Account deleted successfully');
end;
$$;

grant execute on function public.delete_user_account() to authenticated;


