-- 2. CONFESSIONS COMMENT COUNTER TRIGGER & REALTIME
ALTER TABLE public.confessions ADD COLUMN IF NOT EXISTS comment_count integer DEFAULT 0;

CREATE OR REPLACE FUNCTION public.sync_confession_comment_count()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE public.confessions
        SET comment_count = COALESCE(comment_count, 0) + 1
        WHERE id = NEW.confession_id;
        RETURN NEW;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE public.confessions
        SET comment_count = GREATEST(0, COALESCE(comment_count, 0) - 1)
        WHERE id = OLD.confession_id;
        RETURN OLD;
    END IF;
    RETURN NULL;
END;
$$;

DROP TRIGGER IF EXISTS trg_confession_comment_counter ON public.confession_comments;
CREATE TRIGGER trg_confession_comment_counter
AFTER INSERT OR DELETE ON public.confession_comments
FOR EACH ROW
EXECUTE FUNCTION public.sync_confession_comment_count();

-- Backfill existing comment counts
UPDATE public.confessions c
SET comment_count = (
    SELECT count(*)
    FROM public.confession_comments cc
    WHERE cc.confession_id = c.id
);

-- Ensure confession_comments is in supabase_realtime publication
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_publication_tables 
        WHERE pubname = 'supabase_realtime' AND tablename = 'confession_comments'
    ) THEN
        ALTER PUBLICATION supabase_realtime ADD TABLE public.confession_comments;
    END IF;
END $$;

-- 3. ATOMIC CHAT VIBE (₦500 WALLET DEDUCTION & MATCH/CONVERSATION ACTIVATION)
CREATE OR REPLACE FUNCTION public.send_chat_vibe(p_recipient_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_sender_id uuid := auth.uid();
    v_wallet_id uuid;
    v_balance numeric(12, 2);
    v_cost numeric(12, 2) := 500.00;
    v_balance_after numeric(12, 2);
    v_tx_ref text := 'vibe-' || gen_random_uuid()::text;
    v_match_id uuid;
    v_sender_name text;
    v_recipient_name text;
    v_user1 uuid;
    v_user2 uuid;
BEGIN
    -- Validation
    IF v_sender_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Authentication required.');
    END IF;

    IF v_sender_id = p_recipient_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'You cannot send a chat vibe to yourself.');
    END IF;

    -- Check if communication is blocked
    IF EXISTS (
        SELECT 1 FROM public.user_blocks
        WHERE (blocker_id = v_sender_id AND blocked_id = p_recipient_id)
           OR (blocker_id = p_recipient_id AND blocked_id = v_sender_id)
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Communication is blocked between these accounts.');
    END IF;

    -- Fetch sender name
    SELECT full_name INTO v_sender_name FROM public.profiles WHERE id = v_sender_id;
    SELECT full_name INTO v_recipient_name FROM public.profiles WHERE id = p_recipient_id;

    IF v_recipient_name IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Recipient not found.');
    END IF;

    -- Lock and check sender wallet
    SELECT id, COALESCE(available_balance, 0)
    INTO v_wallet_id, v_balance
    FROM public.wallets
    WHERE user_id = v_sender_id
    FOR UPDATE;

    IF v_wallet_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Wallet not found. Please visit Wallet page.');
    END IF;

    IF v_balance < v_cost THEN
        RETURN jsonb_build_object(
            'success', false, 
            'error', 'Insufficient wallet balance. Chat Vibe requires ₦500.',
            'available_balance', v_balance,
            'required_amount', v_cost
        );
    END IF;

    -- Deduct ₦500 from sender wallet
    v_balance_after := v_balance - v_cost;
    UPDATE public.wallets
    SET available_balance = v_balance_after,
        total_spent = COALESCE(total_spent, 0) + v_cost,
        updated_at = now()
    WHERE id = v_wallet_id;

    -- Record in wallet_ledger
    INSERT INTO public.wallet_ledger (
        user_id,
        wallet_id,
        entry_type,
        amount,
        currency,
        source,
        source_reference,
        status,
        balance_before,
        balance_after,
        metadata
    ) VALUES (
        v_sender_id,
        v_wallet_id,
        'debit',
        v_cost,
        'NGN',
        'chat_vibe',
        v_tx_ref,
        'posted',
        v_balance,
        v_balance_after,
        jsonb_build_object('recipient_id', p_recipient_id, 'feature', 'chat_vibe')
    );

    -- Record in wallet_transactions
    INSERT INTO public.wallet_transactions (
        user_id,
        wallet_id,
        type,
        amount,
        status,
        description,
        payment_method,
        reference_id,
        metadata
    ) VALUES (
        v_sender_id,
        v_wallet_id,
        'service_payment',
        v_cost,
        'successful',
        'Direct Chat Vibe to ' || COALESCE(v_recipient_name, 'Campus Student'),
        'wallet',
        v_tx_ref,
        jsonb_build_object('recipient_id', p_recipient_id, 'feature', 'chat_vibe')
    );

    -- Create or fetch mutual match
    IF v_sender_id < p_recipient_id THEN
        v_user1 := v_sender_id;
        v_user2 := p_recipient_id;
    ELSE
        v_user1 := p_recipient_id;
        v_user2 := v_sender_id;
    END IF;

    SELECT id INTO v_match_id
    FROM public.matches
    WHERE (user1_id = v_user1 AND user2_id = v_user2);

    IF v_match_id IS NULL THEN
        INSERT INTO public.matches (
            user1_id,
            user2_id,
            user_ids,
            created_at
        ) VALUES (
            v_user1,
            v_user2,
            ARRAY[v_user1, v_user2],
            now()
        ) RETURNING id INTO v_match_id;
    END IF;


    -- Insert system introductory message
    INSERT INTO public.messages (
        match_id,
        sender_id,
        receiver_id,
        content,
        type,
        metadata,
        created_at
    ) VALUES (
        v_match_id,
        v_sender_id,
        p_recipient_id,
        '✨ ' || COALESCE(v_sender_name, 'Someone') || ' started a Chat Vibe! (₦500 Vibe Unlocked)',
        'system',
        jsonb_build_object('vibe_reference', v_tx_ref, 'cost', v_cost),
        now()
    );

    RETURN jsonb_build_object(
        'success', true,
        'match_id', v_match_id,
        'balance_after', v_balance_after,
        'cost', v_cost,
        'reference', v_tx_ref
    );
END;
$$;

GRANT EXECUTE ON FUNCTION public.send_chat_vibe(uuid) TO authenticated;


-- -----------------------------------------------------------------------------
-- [Migration: 20260913160000_grant_cofounder_admin_jackreecesokieprim.sql]
-- -----------------------------------------------------------------------------
-- ============================================================================
-- Migration: 20260913160000_grant_cofounder_admin_jackreecesokieprim.sql
-- Description:
--   Grants full co-founder administrator privileges to jackreecesokieprim@gmail.com.
--   1. Updates is_app_admin() to recognize jackreecesokieprim@gmail.com.
--   2. Updates admin_is_owner() to recognize jackreecesokieprim@gmail.com as platform owner/co-founder.
--   3. Updates admin_has_permission() so jackreecesokieprim@gmail.com retains all permissions (*).
--   4. Updates admin_get_my_access() to return owner role and full access.
--   5. Updates admin_get_admin_access_list() to display co-founder under owner section.
--   6. Protects co-founder from revocation in admin_update_admin_access() and admin_invite_admin().
--   7. Updates auth.users app_metadata with { is_admin: true, role: 'owner', admin_permissions: ['*'] }.
-- ============================================================================

-- 1. Update is_app_admin()
CREATE OR REPLACE FUNCTION public.is_app_admin()
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
declare
  v_user auth.users;
  v_email text;
begin
  if auth.uid() is null then
    return false;
  end if;

  select *
  into v_user
  from auth.users
  where id = auth.uid();

  if v_user.id is null then
    return false;
  end if;

  v_email := lower(coalesce(v_user.email, ''));

  if v_email in ('godwillgodslife@gmail.com', 'godswillgodwillgodlife@gmail.com', 'jackreecesokieprim@gmail.com') then
    return true;
  end if;

  return coalesce((v_user.raw_app_meta_data->>'is_admin')::boolean, false) = true
    or v_user.raw_app_meta_data->>'role' in ('admin', 'owner', 'super_admin')
    or jsonb_typeof(v_user.raw_app_meta_data->'admin_permissions') = 'array';
end;
$function$;

-- 2. Update admin_is_owner()
CREATE OR REPLACE FUNCTION public.admin_is_owner()
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
declare
  v_user auth.users;
  v_email text;
begin
  if auth.uid() is null then
    return false;
  end if;

  select *
  into v_user
  from auth.users
  where id = auth.uid();

  if v_user.id is null then
    return false;
  end if;

  v_email := lower(coalesce(v_user.email, ''));

  return v_email in ('godwillgodslife@gmail.com', 'godswillgodwillgodlife@gmail.com', 'jackreecesokieprim@gmail.com')
    or v_user.raw_app_meta_data->>'role' in ('owner', 'super_admin');
end;
$function$;

-- 3. Update admin_has_permission()
CREATE OR REPLACE FUNCTION public.admin_has_permission(p_permission text)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
declare
  v_user auth.users;
  v_email text;
  v_permission text := lower(nullif(trim(coalesce(p_permission, '')), ''));
  v_permissions jsonb;
  v_aliases text[];
begin
  if v_permission is null or auth.uid() is null then
    return false;
  end if;

  select *
  into v_user
  from auth.users
  where id = auth.uid();

  if v_user.id is null then
    return false;
  end if;

  v_email := lower(coalesce(v_user.email, ''));
  v_permissions := v_user.raw_app_meta_data->'admin_permissions';

  -- Owner / Co-founder always has all permissions (immutable)
  if v_email in ('godwillgodslife@gmail.com', 'godswillgodwillgodlife@gmail.com', 'jackreecesokieprim@gmail.com') then
    return true;
  end if;

  if v_user.raw_app_meta_data->>'role' in ('owner', 'super_admin') then
    return true;
  end if;

  -- Build equivalent aliases between dot notation and colon notation
  case v_permission
    when 'users.view', 'users:read' then v_aliases := array['users.view', 'users:read', 'users.manage', 'users:moderate'];
    when 'users.manage', 'users:moderate' then v_aliases := array['users.manage', 'users:moderate'];
    when 'profiles.view' then v_aliases := array['profiles.view', 'users.view', 'users:read'];
    when 'profiles.moderate' then v_aliases := array['profiles.moderate', 'users.manage', 'users:moderate'];
    when 'content.manage', 'content:moderate' then v_aliases := array['content.manage', 'content:moderate'];
    when 'reports.view', 'reports.manage' then v_aliases := array['reports.view', 'reports.manage', 'content.manage', 'content:moderate'];
    when 'finance.read', 'payments.view', 'subscriptions.view', 'transactions.view', 'wallets.view' then
      v_aliases := array['finance.read', 'finance:read', 'payments.view', 'subscriptions.view', 'transactions.view', 'wallets.view'];
    when 'finance.payouts', 'wallets.manage', 'refunds.manage' then
      v_aliases := array['finance.payouts', 'finance:payouts', 'wallets.manage', 'refunds.manage'];
    when 'config.write', 'config:write', 'settings.manage' then
      v_aliases := array['config.write', 'config:write', 'settings.manage'];
    when 'promo.write', 'promo:write' then
      v_aliases := array['promo.write', 'promo:write'];
    when 'push.broadcast', 'push:broadcast', 'notifications.send', 'notifications.manage' then
      v_aliases := array['push.broadcast', 'push:broadcast', 'notifications.send', 'notifications.manage'];
    when 'audit.read', 'audit:read' then
      v_aliases := array['audit.read', 'audit:read'];
    when 'analytics.view' then
      v_aliases := array['analytics.view', 'finance.read', 'finance:read'];
    when 'admins.view', 'admins.manage' then
      v_aliases := array['admins.view', 'admins.manage'];
    else
      v_aliases := array[v_permission];
  end case;

  if jsonb_typeof(v_permissions) = 'array' then
    if v_permissions ? '*' then
      return true;
    end if;

    for i in 1..coalesce(array_length(v_aliases, 1), 0) loop
      if v_permissions ? v_aliases[i] then
        return true;
      end if;
    end loop;
    return false;
  end if;

  -- Strictly deny high-privilege access for legacy accounts without explicit permissions
  if coalesce((v_user.raw_app_meta_data->>'is_admin')::boolean, false) = true or v_user.raw_app_meta_data->>'role' = 'admin' then
    if v_permission in ('admins.manage', 'admins.view', 'finance.payouts', 'config.write', 'settings.manage') then
      return false;
    end if;
    return v_permission in (
      'users.view', 'users:read', 'users.manage', 'users:moderate',
      'profiles.view', 'profiles.moderate',
      'content.manage', 'content:moderate',
      'reports.view', 'reports.manage',
      'finance.read', 'finance:read', 'payments.view', 'subscriptions.view', 'transactions.view', 'wallets.view',
      'promo.write', 'promo:write',
      'push.broadcast', 'push:broadcast', 'notifications.send',
      'audit.read', 'audit:read',
      'analytics.view'
    );
  end if;

  return false;
end;
$function$;

-- 4. Update admin_get_my_access()
CREATE OR REPLACE FUNCTION public.admin_get_my_access()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
declare
  v_user auth.users;
  v_email text;
  v_is_owner boolean := false;
  v_permissions jsonb;
  v_role text;
begin
  if auth.uid() is null then
    raise exception 'Not authorized';
  end if;

  select *
  into v_user
  from auth.users
  where id = auth.uid();

  if v_user.id is null or not public.is_app_admin() then
    raise exception 'Not authorized';
  end if;

  v_email := lower(coalesce(v_user.email, ''));
  v_is_owner := v_email in ('godwillgodslife@gmail.com', 'godswillgodwillgodlife@gmail.com', 'jackreecesokieprim@gmail.com')
    or v_user.raw_app_meta_data->>'role' in ('owner', 'super_admin');
  v_permissions := v_user.raw_app_meta_data->'admin_permissions';
  v_role := case
    when v_is_owner then 'owner'
    when jsonb_typeof(v_permissions) = 'array' then 'restricted_admin'
    when coalesce((v_user.raw_app_meta_data->>'is_admin')::boolean, false) = true
      or v_user.raw_app_meta_data->>'role' = 'admin' then 'legacy_admin'
    else 'admin'
  end;

  return jsonb_build_object(
    'isAdmin', true,
    'role', v_role,
    'isOwner', v_is_owner,
    'permissionMode', case
      when v_is_owner then 'owner_full_access'
      when jsonb_typeof(v_permissions) = 'array' then 'explicit_permissions'
      else 'legacy_full_access'
    end,
    'permissions', case
      when v_is_owner then jsonb_build_array('*')
      when jsonb_typeof(v_permissions) = 'array' then v_permissions
      else jsonb_build_array('*')
    end,
    'email', v_user.email
  );
end;
