-- 3. Create admin_get_user_summary() RPC
CREATE OR REPLACE FUNCTION public.admin_get_user_summary()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
declare
  v_summary jsonb;
begin
  if not (
    public.admin_has_permission('users:read')
    or public.admin_has_permission('users.view')
    or public.admin_has_permission('users:moderate')
    or public.admin_is_owner()
    or public.is_app_admin()
  ) then
    raise exception 'Not authorized';
  end if;

  select jsonb_build_object(
    'total', count(*),
    'onlineNow', count(*) filter (where coalesce(last_seen_at, last_active, last_seen) >= now() - interval '5 minutes'),
    'active24h', count(*) filter (where coalesce(last_seen_at, last_active, last_seen) >= now() - interval '24 hours'),
    'active7d', count(*) filter (where coalesce(last_seen_at, last_active, last_seen) >= now() - interval '7 days'),
    'active30d', count(*) filter (where coalesce(last_seen_at, last_active, last_seen) >= now() - interval '30 days'),
    'inactive', count(*) filter (where coalesce(last_seen_at, last_active, last_seen) < now() - interval '30 days' or coalesce(last_seen_at, last_active, last_seen) is null),
    'goodStanding', count(*) filter (where coalesce(is_banned, false) = false and coalesce(is_shadow_banned, false) = false),
    'shadow', count(*) filter (where coalesce(is_shadow_banned, false) = true),
    'banned', count(*) filter (where coalesce(is_banned, false) = true),
    'verified', count(*) filter (where coalesce(is_verified, false) = true),
    'premium', count(*) filter (where coalesce(is_premium, false) = true),
    'needsReview', count(*) filter (where coalesce(is_banned, false) = true or coalesce(is_shadow_banned, false) = true or coalesce(is_verified, false) = false)
  )
  into v_summary
  from public.profiles;

  return v_summary;
end;
$function$;

-- 4. Upgrade admin_search_users() with p_activity filter & unified last_seen_at / is_online
CREATE OR REPLACE FUNCTION public.admin_search_users(
  p_limit integer default 50,
  p_offset integer default 0,
  p_query text default null,
  p_status text default null,
  p_gender text default null,
  p_university text default null,
  p_verified boolean default null,
  p_premium boolean default null,
  p_activity text default null
)
RETURNS table (
  id uuid,
  full_name text,
  email text,
  gender text,
  university text,
  avatar_url text,
  is_banned boolean,
  is_shadow_banned boolean,
  is_verified boolean,
  is_premium boolean,
  created_at timestamp with time zone,
  last_seen_at timestamp with time zone,
  last_active timestamp with time zone,
  is_online boolean,
  total_count bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 200);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_query text := nullif(trim(coalesce(p_query, '')), '');
  v_status text := lower(nullif(trim(coalesce(p_status, '')), ''));
  v_gender text := lower(nullif(trim(coalesce(p_gender, '')), ''));
  v_university text := nullif(trim(coalesce(p_university, '')), '');
  v_activity text := lower(nullif(trim(coalesce(p_activity, '')), ''));
begin
  if not (
    public.admin_has_permission('users:read')
    or public.admin_has_permission('users.view')
    or public.admin_has_permission('users:moderate')
    or public.admin_is_owner()
    or public.is_app_admin()
  ) then
    raise exception 'Not authorized';
  end if;

  if v_status is not null and v_status not in ('active', 'good_standing', 'banned', 'shadow') then
    raise exception 'Invalid status filter';
  end if;

  if v_activity is not null and v_activity not in ('online', 'active_24h', 'active_7d', 'active_30d', 'inactive') then
    raise exception 'Invalid activity filter';
  end if;

  return query
  with filtered as (
    select p.*
    from public.profiles p
    where
      (
        v_query is null
        or coalesce(p.full_name, '') ilike '%' || v_query || '%'
        or coalesce(p.email, '') ilike '%' || v_query || '%'
        or p.id::text = v_query
      )
      and (
        v_status is null
        or (v_status = 'banned' and coalesce(p.is_banned, false))
        or (v_status = 'shadow' and coalesce(p.is_shadow_banned, false))
        or (
          v_status in ('active', 'good_standing')
          and not coalesce(p.is_banned, false)
          and not coalesce(p.is_shadow_banned, false)
        )
      )
      and (
        v_activity is null
        or (v_activity = 'online' and coalesce(p.last_seen_at, p.last_active, p.last_seen) >= now() - interval '5 minutes')
        or (v_activity = 'active_24h' and coalesce(p.last_seen_at, p.last_active, p.last_seen) >= now() - interval '24 hours')
        or (v_activity = 'active_7d' and coalesce(p.last_seen_at, p.last_active, p.last_seen) >= now() - interval '7 days')
        or (v_activity = 'active_30d' and coalesce(p.last_seen_at, p.last_active, p.last_seen) >= now() - interval '30 days')
        or (v_activity = 'inactive' and (coalesce(p.last_seen_at, p.last_active, p.last_seen) < now() - interval '30 days' or coalesce(p.last_seen_at, p.last_active, p.last_seen) is null))
      )
      and (v_gender is null or lower(coalesce(p.gender, '')) = v_gender)
      and (v_university is null or coalesce(p.university, '') ilike '%' || v_university || '%')
      and (p_verified is null or coalesce(p.is_verified, false) = p_verified)
      and (p_premium is null or coalesce(p.is_premium, false) = p_premium)
  )
  select
    f.id,
    f.full_name::text,
    f.email::text,
    f.gender::text,
    f.university::text,
    f.avatar_url::text,
    coalesce(f.is_banned, false),
    coalesce(f.is_shadow_banned, false),
    coalesce(f.is_verified, false),
    coalesce(f.is_premium, false),
    f.created_at,
    coalesce(f.last_seen_at, f.last_active, f.last_seen) as last_seen_at,
    f.last_active,
    (coalesce(f.last_seen_at, f.last_active, f.last_seen) >= now() - interval '5 minutes') as is_online,
    count(*) over()::bigint as total_count
  from filtered f
  order by
    case when v_activity in ('online', 'active_24h', 'active_7d', 'active_30d') then coalesce(f.last_seen_at, f.last_active, f.last_seen) end desc nulls last,
    f.created_at desc nulls last
  limit v_limit
  offset v_offset;
end;
$function$;

-- 5. Clean up stale sticky is_online / is_live flags in profiles
UPDATE public.profiles
SET is_online = false,
    is_live = false
WHERE coalesce(last_seen_at, last_active, last_seen) < now() - interval '10 minutes'
   OR coalesce(last_seen_at, last_active, last_seen) IS NULL;

-- 6. Revoke and grant execution permissions
REVOKE ALL ON FUNCTION public.admin_get_ops_snapshot() FROM public, anon;
REVOKE ALL ON FUNCTION public.admin_get_dashboard_stats() FROM public, anon;
REVOKE ALL ON FUNCTION public.admin_get_user_summary() FROM public, anon;
REVOKE ALL ON FUNCTION public.admin_search_users(integer, integer, text, text, text, text, boolean, boolean, text) FROM public, anon;

GRANT EXECUTE ON FUNCTION public.admin_get_ops_snapshot() TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_get_dashboard_stats() TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_get_user_summary() TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_search_users(integer, integer, text, text, text, text, boolean, boolean, text) TO authenticated;


-- -----------------------------------------------------------------------------
-- [Migration: 20260915120000_confession_views_and_reactions.sql]
-- -----------------------------------------------------------------------------
-- ==============================================================================
-- Migration: 20260915120000_confession_views_and_reactions.sql
-- Description: Adds view_count column to confessions, updates optimized_confessions view,
--              expands confession_reactions emoji constraint, and adds increment_confession_view RPC.
-- ==============================================================================

-- 1. ADD view_count COLUMN TO CONFESSIONS
ALTER TABLE public.confessions ADD COLUMN IF NOT EXISTS view_count integer DEFAULT 0;

-- 2. EXPAND VALID EMOJIS CONSTRAINT ON confession_reactions
ALTER TABLE public.confession_reactions DROP CONSTRAINT IF EXISTS valid_emoji;
ALTER TABLE public.confession_reactions
    ADD CONSTRAINT valid_emoji CHECK (
        emoji IN (
            '❤️', '🔥', '😂', '🙊', '🙏', '😢', '😡', '🙈', '👀',
            U&'\2764',          -- heavy black heart
            U&'\D83D\DD25',      -- fire
            U&'\D83D\DE02',      -- laughing
            U&'\D83D\DE4A',      -- see-no-evil monkey
            U&'\D83D\DE4F',      -- pray/folded hands
            U&'\D83D\DE22',      -- crying
            U&'\D83D\DE21',      -- pouting/angry
            U&'\D83D\DE48',      -- see-no-evil monkey alternate
            U&'\D83D\DC40'       -- eyes
        )
    );

-- 3. RECREATE OPTIMIZED_CONFESSIONS VIEW WITH view_count
DROP VIEW IF EXISTS public.optimized_confessions CASCADE;
CREATE OR REPLACE VIEW public.optimized_confessions AS
SELECT 
    c.id,
    c.content,
    c.university,
    c.user_id,
    c.created_at,
    COALESCE(r.reaction_data, '[]'::jsonb) as reaction_data,
    COALESCE(r.total_reactions, 0) as total_reactions,
    COALESCE(c.comment_count, comm.comment_count, 0) as comment_count,
    COALESCE(cl.claimer_ids, '[]'::jsonb) as claimer_ids,
    (COALESCE(r.total_reactions, 0) >= 20) as is_viral,
    COALESCE(c.post_type, 'anonymous_confession') as post_type,
    COALESCE(c.is_anonymous, true) as is_anonymous,
    c.author_name,
    c.author_avatar,
    c.author_username,
    c.image_url,
    COALESCE(c.repost_count, 0) as repost_count,
    COALESCE(c.view_count, 0) as view_count
FROM public.confessions c
LEFT JOIN (
    SELECT 
        confession_id,
        jsonb_agg(jsonb_build_object('u', user_id, 'e', emoji)) as reaction_data,
        COUNT(*) as total_reactions
    FROM public.confession_reactions
    GROUP BY confession_id
) r ON c.id = r.confession_id
LEFT JOIN (
    SELECT confession_id, COUNT(*) as comment_count
    FROM public.confession_comments
    GROUP BY confession_id
) comm ON c.id = comm.confession_id
LEFT JOIN (
    SELECT confession_id, jsonb_agg(claimer_id) as claimer_ids
    FROM public.confession_claims
    GROUP BY confession_id
) cl ON c.id = cl.confession_id;

GRANT SELECT ON public.optimized_confessions TO anon, authenticated;

-- 4. RPC TO ATOMICALLY INCREMENT CONFESSION VIEW COUNT
CREATE OR REPLACE FUNCTION public.increment_confession_view(p_confession_id uuid)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_views integer;
BEGIN
    UPDATE public.confessions
    SET view_count = COALESCE(view_count, 0) + 1
    WHERE id = p_confession_id
    RETURNING view_count INTO v_views;

    RETURN COALESCE(v_views, 0);
END;
$$;

REVOKE ALL ON FUNCTION public.increment_confession_view(uuid) FROM public;
GRANT EXECUTE ON FUNCTION public.increment_confession_view(uuid) TO anon, authenticated;


-- -----------------------------------------------------------------------------
-- [Migration: 20260916090000_android_final_fixes.sql]
-- -----------------------------------------------------------------------------
-- Migration: 20260916090000_android_final_fixes.sql
-- Description: 
-- 1. Security definer RPC for public anonymous ask profiles (fixes "Student Not Found")
-- 2. Security definer RPC for anonymous ask message submission (fixes RLS policy violation)
-- 3. ₦100,000 "Lion" coin package in purchase_coins_with_wallet (25,000 coins)
-- 4. ₦100,000 "Campus Lion" gift in send_coin_gift (10,000 coins, ₦80,000 earning credit)

-- ============================================================================
-- 1. PUBLIC ASK PROFILE RPC (Security Definer)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_public_ask_profile(p_username_or_id text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_clean text;
    v_is_uuid boolean;
    v_profile record;
BEGIN
    IF p_username_or_id IS NULL OR length(trim(p_username_or_id)) = 0 THEN
        RETURN NULL;
    END IF;

    v_clean := lower(trim(leading '@' from trim(p_username_or_id)));
    v_is_uuid := p_username_or_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

    IF v_is_uuid THEN
        SELECT id, full_name, username, avatar_url, university, is_verified, bio, video_url
        INTO v_profile
        FROM public.profiles
        WHERE id = p_username_or_id::uuid
          AND COALESCE(is_banned, false) = false
        LIMIT 1;
    ELSE
        SELECT id, full_name, username, avatar_url, university, is_verified, bio, video_url
        INTO v_profile
        FROM public.profiles
        WHERE lower(username) = v_clean
          AND COALESCE(is_banned, false) = false
        LIMIT 1;
    END IF;

    IF v_profile.id IS NULL THEN
        RETURN NULL;
    END IF;

    RETURN to_jsonb(v_profile);
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_public_ask_profile(text) TO anon, authenticated, service_role;

-- ============================================================================
-- 2. ANONYMOUS ASK MESSAGE SUBMISSION RPC (Security Definer)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.submit_anonymous_ask_message(
    p_recipient_id uuid,
    p_content text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_rec public.user_anonymous_messages%ROWTYPE;
    v_username text;
    v_snippet text;
BEGIN
    IF p_content IS NULL OR length(trim(p_content)) = 0 THEN
        RAISE EXCEPTION 'Message content cannot be empty';
    END IF;

    IF p_recipient_id IS NULL THEN
        RAISE EXCEPTION 'Recipient ID is required';
    END IF;

    SELECT username INTO v_username
    FROM public.profiles
    WHERE id = p_recipient_id
      AND COALESCE(is_banned, false) = false;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Recipient student not found or account is inactive';
    END IF;

    INSERT INTO public.user_anonymous_messages (
        recipient_id,
        recipient_username,
        content
    ) VALUES (
        p_recipient_id,
        COALESCE(v_username, 'student'),
        trim(p_content)
    )
    RETURNING * INTO v_rec;

    -- Send notification to recipient
    v_snippet := substring(trim(p_content) from 1 for 35);
    BEGIN
        INSERT INTO public.notifications (
            user_id,
            actor_id,
            type,
            title,
            content,
            metadata
        ) VALUES (
            p_recipient_id,
            NULL,
            'snapshot_reaction',
            'New Anonymous Message 💌',
            'Someone sent you an anonymous message: "' || v_snippet || '..."',
            '{"url": "/confessions?tab=inbox"}'::jsonb
        );
    EXCEPTION WHEN OTHERS THEN
        -- Defensive ignore notification errors
    END;

    RETURN to_jsonb(v_rec);
END;
$$;

GRANT EXECUTE ON FUNCTION public.submit_anonymous_ask_message(uuid, text) TO anon, authenticated, service_role;

-- Ensure public insert policy and permissions on user_anonymous_messages
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM information_schema.tables 
        WHERE table_schema = 'public' AND table_name = 'user_anonymous_messages'
    ) THEN
        GRANT INSERT ON TABLE public.user_anonymous_messages TO anon, authenticated;
        GRANT SELECT, UPDATE, DELETE ON TABLE public.user_anonymous_messages TO authenticated;
        GRANT ALL ON TABLE public.user_anonymous_messages TO service_role;
    END IF;
END $$;

-- ============================================================================
-- 3. ₦100,000 LION COIN PACKAGE IN purchase_coins_with_wallet
-- ============================================================================

CREATE OR REPLACE FUNCTION public.purchase_coins_with_wallet(p_package_id TEXT)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_wallet public.wallets%ROWTYPE;
    v_coins_to_add INTEGER;
    v_cost_ngn NUMERIC(12,2);
    v_balance_after INTEGER;
    v_ref TEXT;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Authentication required');
    END IF;

    CASE p_package_id
        WHEN 'coins_starter' THEN
            v_coins_to_add := 100;
            v_cost_ngn := 900.00;
        WHEN 'coins_popular' THEN
            v_coins_to_add := 400;
            v_cost_ngn := 2500.00;
        WHEN 'coins_elite' THEN
            v_coins_to_add := 950;
            v_cost_ngn := 5000.00;
        WHEN 'coins_vip' THEN
            v_coins_to_add := 2500;
            v_cost_ngn := 10000.00;
        WHEN 'coins_lion' THEN
            v_coins_to_add := 25000;
            v_cost_ngn := 100000.00;
        ELSE
            RETURN jsonb_build_object('success', false, 'error', 'Invalid coin package');
    END CASE;

    SELECT * INTO v_wallet
    FROM public.wallets
    WHERE user_id = v_user_id
    FOR UPDATE;

    IF NOT FOUND OR coalesce(v_wallet.available_balance, 0) < v_cost_ngn THEN
        RETURN jsonb_build_object('success', false, 'error', 'Insufficient wallet balance. Please top up your wallet.');
    END IF;

    v_ref := 'coin_wall_' || v_user_id || '_' || extract(epoch from now())::bigint;

    UPDATE public.wallets
    SET available_balance = available_balance - v_cost_ngn,
        total_spent = coalesce(total_spent, 0) + v_cost_ngn,
        updated_at = now()
    WHERE id = v_wallet.id;

    INSERT INTO public.wallet_ledger (
        user_id, wallet_id, entry_type, amount, currency, source, source_reference, status, balance_before, balance_after, metadata
    ) VALUES (
        v_user_id, v_wallet.id, 'debit', v_cost_ngn, 'NGN', 'coin_purchase', v_ref, 'posted',
        v_wallet.available_balance, v_wallet.available_balance - v_cost_ngn,
        jsonb_build_object('package_id', p_package_id, 'coins_granted', v_coins_to_add)
    );

    UPDATE public.profiles
    SET coins = coalesce(coins, 0) + v_coins_to_add
    WHERE id = v_user_id
    RETURNING coins INTO v_balance_after;

    INSERT INTO public.coin_transactions (
        user_id, amount, balance_after, transaction_type, reference, source, metadata
    ) VALUES (
        v_user_id, v_coins_to_add, v_balance_after, 'purchase', v_ref, 'wallet_conversion',
        jsonb_build_object('package_id', p_package_id, 'cost_ngn', v_cost_ngn)
    );

    RETURN jsonb_build_object(
        'success', true,
        'new_coin_balance', v_balance_after,
        'new_wallet_balance', v_wallet.available_balance - v_cost_ngn,
        'coins_added', v_coins_to_add
    );
END;
$$;

GRANT EXECUTE ON FUNCTION public.purchase_coins_with_wallet(TEXT) TO authenticated;

-- ============================================================================
-- 4. ₦100,000 CAMPUS LION GIFT IN send_coin_gift
-- ============================================================================

CREATE OR REPLACE FUNCTION public.send_coin_gift(
    p_receiver_id UUID,
    p_gift_id TEXT,
    p_match_id UUID
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_sender_id UUID := auth.uid();
    v_sender_coins INTEGER;
    v_gift_cost INTEGER;
    v_gift_name TEXT;
    v_gift_emoji TEXT;
    v_gift_color TEXT;
    v_earning_credit NUMERIC(12,2);
    v_receiver_wallet_id UUID;
    v_tx_ref TEXT;
    v_msg_id UUID;
BEGIN
    IF v_sender_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Authentication required');
    END IF;

    IF v_sender_id = p_receiver_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'Cannot send gifts to yourself');
    END IF;

    IF EXISTS (
        SELECT 1 FROM public.user_blocks
        WHERE (blocker_id = v_sender_id AND blocked_id = p_receiver_id)
           OR (blocker_id = p_receiver_id AND blocked_id = v_sender_id)
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Communication is blocked with this user');
    END IF;

    CASE p_gift_id
        WHEN 'rose' THEN
            v_gift_cost := 20;
            v_gift_name := 'Digital Rose';
            v_gift_emoji := '🌹';
            v_gift_color := '#f43f5e';
        WHEN 'zobo' THEN
            v_gift_cost := 20;
            v_gift_name := 'Cold Zobo';
            v_gift_emoji := '🍷';
            v_gift_color := '#9d174d';
        WHEN 'suya' THEN
            v_gift_cost := 50;
            v_gift_name := 'Hot Suya';
            v_gift_emoji := '🍢';
            v_gift_color := '#ea580c';
        WHEN 'airtime' THEN
            v_gift_cost := 100;
            v_gift_name := 'Airtime Charm';
            v_gift_emoji := '📱';
            v_gift_color := '#2563eb';
        WHEN 'bouquet' THEN
            v_gift_cost := 200;
            v_gift_name := 'Campus Bouquet';
            v_gift_emoji := '💐';
            v_gift_color := '#10b981';
        WHEN 'crown' THEN
            v_gift_cost := 500;
            v_gift_name := 'Royal Crown';
            v_gift_emoji := '👑';
            v_gift_color := '#ffd700';
        WHEN 'lion' THEN
            v_gift_cost := 10000;
            v_gift_name := 'Campus Lion';
            v_gift_emoji := '🦁';
            v_gift_color := '#f59e0b';
        ELSE
            RETURN jsonb_build_object('success', false, 'error', 'Unknown gift ID');
    END CASE;

    SELECT coins INTO v_sender_coins
    FROM public.profiles
    WHERE id = v_sender_id
    FOR UPDATE;

    IF coalesce(v_sender_coins, 0) < v_gift_cost THEN
        RETURN jsonb_build_object('success', false, 'error', 'Insufficient CD Coins. Please recharge your coins.');
    END IF;

    v_tx_ref := 'gift_' || v_sender_id || '_' || extract(epoch from now())::bigint;

    UPDATE public.profiles
    SET coins = coins - v_gift_cost
    WHERE id = v_sender_id
    RETURNING coins INTO v_sender_coins;

    INSERT INTO public.coin_transactions (
        user_id, amount, balance_after, transaction_type, reference, source, destination_user_id, metadata
    ) VALUES (
        v_sender_id, -v_gift_cost, v_sender_coins, 'gift_sent', v_tx_ref, 'gift_store', p_receiver_id,
        jsonb_build_object('gift_id', p_gift_id, 'gift_name', v_gift_name, 'match_id', p_match_id)
    );

    -- 80% split back to student receiver wallet: 10,000 coins * 10 * 0.8 = ₦80,000 credit
    v_earning_credit := (v_gift_cost * 10 * 0.8)::numeric(12,2);
    
    INSERT INTO public.wallets (user_id, available_balance, total_earned)
    VALUES (p_receiver_id, 0, 0)
    ON CONFLICT (user_id) DO NOTHING;

    SELECT id INTO v_receiver_wallet_id
    FROM public.wallets
    WHERE user_id = p_receiver_id;

    IF v_receiver_wallet_id IS NOT NULL THEN
        UPDATE public.wallets
        SET available_balance = available_balance + v_earning_credit,
            total_earned = coalesce(total_earned, 0) + v_earning_credit,
            updated_at = now()
        WHERE id = v_receiver_wallet_id;

        INSERT INTO public.wallet_transactions (
            user_id, wallet_id, type, amount, status, description, metadata
        ) VALUES (
            p_receiver_id, v_receiver_wallet_id, 'gift_received', v_earning_credit, 'completed',
            'Gift received: ' || v_gift_name,
            jsonb_build_object('gift_id', p_gift_id, 'sender_id', v_sender_id, 'gift_coins', v_gift_cost)
        );
    END IF;

    INSERT INTO public.messages (
        match_id, sender_id, content, type, metadata
    ) VALUES (
        p_match_id, v_sender_id, 'Sent ' || v_gift_name || ' ' || v_gift_emoji, 'gift',
        jsonb_build_object(
            'gift_id', p_gift_id,
            'gift_name', v_gift_name,
            'gift_emoji', v_gift_emoji,
            'gift_color', v_gift_color,
            'gift_coins', v_gift_cost
        )
    )
    RETURNING id INTO v_msg_id;

    RETURN jsonb_build_object(
        'success', true,
        'remaining_coins', v_sender_coins,
        'gift_name', v_gift_name,
        'gift_emoji', v_gift_emoji,
        'message_id', v_msg_id
    );
END;
$$;

GRANT EXECUTE ON FUNCTION public.send_coin_gift(UUID, TEXT, UUID) TO authenticated;


