GRANT SELECT ON TABLE public.notification_email_queue TO authenticated;
GRANT ALL ON TABLE public.notification_email_queue TO service_role;

-- 4. Trigger Function: Enqueue Delayed Notification Email
CREATE OR REPLACE FUNCTION public.trg_fn_notifications_enqueue_delayed_email()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_target_user_id uuid;
    v_actor_id uuid;
    v_conv_id uuid;
    v_dedupe_key text;
    v_email_enabled boolean;
    v_action_url text;
BEGIN
    -- 1. Guard against already read notifications or explicit suppression
    IF NEW.is_read = true 
       OR NEW.metadata->>'suppress_email' = 'true' 
       OR NEW.metadata->>'suppressEmail' = 'true' 
       OR NEW.metadata->>'recipientIsActive' = 'true' THEN
        RETURN NEW;
    END IF;

    -- 2. Resolve target user and actor
    v_target_user_id := COALESCE(NEW.user_id, NEW.recipient_id);
    IF v_target_user_id IS NULL THEN
        RETURN NEW;
    END IF;

    v_actor_id := COALESCE(NEW.actor_id, NEW.sender_id);
    IF (NEW.metadata->>'is_anonymous') = 'true' OR NEW.type = 'confession' THEN
        v_actor_id := NULL;
    END IF;

    -- 3. Check user profile email preference
    SELECT email_notifications INTO v_email_enabled
    FROM public.profiles
    WHERE id = v_target_user_id;

    IF v_email_enabled = false THEN
        RETURN NEW;
    END IF;

    -- 4. Resolve conversation ID (for chat deduplication)
    v_conv_id := COALESCE(
        NEW.conversation_id,
        NEW.match_id,
        CASE WHEN (NEW.metadata->>'match_id') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' 
             THEN (NEW.metadata->>'match_id')::uuid ELSE NULL END,
        CASE WHEN (NEW.metadata->>'conversation_id') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' 
             THEN (NEW.metadata->>'conversation_id')::uuid ELSE NULL END
    );

    -- 5. Construct dedupe_key (matching PROJECT.md Interface Contract 2)
    IF NEW.category = 'messages' OR NEW.type IN ('message', 'chat') OR v_conv_id IS NOT NULL THEN
        IF v_conv_id IS NOT NULL THEN
            v_dedupe_key := 'email:chat:' || v_target_user_id::text || ':' || v_conv_id::text;
        ELSE
            v_dedupe_key := 'email:chat:' || v_target_user_id::text || ':' || NEW.id::text;
        END IF;
    ELSIF NEW.category = 'requests' OR NEW.type IN ('request', 'connection_request', 'message_request') THEN
        v_dedupe_key := 'email:request:' || v_target_user_id::text;
    ELSIF NEW.category = 'matches' OR NEW.type IN ('match', 'like', 'super_swipe') THEN
        v_dedupe_key := 'email:match:' || v_target_user_id::text || ':' || COALESCE(v_conv_id::text, NEW.id::text);
    ELSE
        v_dedupe_key := 'email:' || v_target_user_id::text || ':' || NEW.id::text;
    END IF;

    -- 6. Resolve Action URL
    v_action_url := COALESCE(NEW.deep_link, NEW.metadata->>'url');

    -- 7. Insert with exception containment block
    BEGIN
        INSERT INTO public.notification_email_queue (
            notification_id,
            user_id,
            actor_id,
            category,
            type,
            title,
            content,
            body,
            action_url,
            dedupe_key,
            status,
            scheduled_for,
            metadata
        )
        VALUES (
            NEW.id,
            v_target_user_id,
            v_actor_id,
            COALESCE(NEW.category, 'general'),
            NEW.type,
            NEW.title,
            NEW.content,
            NEW.content,
            v_action_url,
            v_dedupe_key,
            'pending',
            now() + interval '15 minutes',
            COALESCE(NEW.metadata, '{}'::jsonb)
        )
        ON CONFLICT (dedupe_key) WHERE status = 'pending'
        DO UPDATE SET
            notification_id = EXCLUDED.notification_id,
            title = EXCLUDED.title,
            content = EXCLUDED.content,
            body = EXCLUDED.content,
            action_url = COALESCE(EXCLUDED.action_url, public.notification_email_queue.action_url),
            metadata = EXCLUDED.metadata,
            updated_at = now();
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'Failed to enqueue notification email: %', SQLERRM;
    END;

    RETURN NEW;
END;
$$;

GRANT EXECUTE ON FUNCTION public.trg_fn_notifications_enqueue_delayed_email() TO authenticated, service_role, anon;

DROP TRIGGER IF EXISTS trg_notifications_enqueue_delayed_email ON public.notifications;
CREATE TRIGGER trg_notifications_enqueue_delayed_email
    AFTER INSERT ON public.notifications
    FOR EACH ROW
    EXECUTE FUNCTION public.trg_fn_notifications_enqueue_delayed_email();

-- 5. Trigger Function: Cancel Delayed Email on Notification Read
CREATE OR REPLACE FUNCTION public.trg_fn_notifications_cancel_delayed_email_on_read()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    -- Fire whenever notification transitions to read or seen
    IF (NEW.is_read = true AND OLD.is_read IS DISTINCT FROM true)
       OR (NEW.read_at IS NOT NULL AND OLD.read_at IS NULL) THEN
        
        BEGIN
            UPDATE public.notification_email_queue
            SET status = 'cancelled_read',
                cancelled_at = now(),
                updated_at = now()
            WHERE status = 'pending'
              AND (
                  notification_id = NEW.id
                  OR (
                      user_id = COALESCE(NEW.user_id, NEW.recipient_id)
                      AND (
                          (NEW.category = 'requests' AND dedupe_key = 'email:request:' || COALESCE(NEW.user_id, NEW.recipient_id)::text)
                          OR (
                              COALESCE(NEW.conversation_id, NEW.match_id) IS NOT NULL
                              AND dedupe_key = 'email:chat:' || COALESCE(NEW.user_id, NEW.recipient_id)::text || ':' || COALESCE(NEW.conversation_id, NEW.match_id)::text
                          )
                      )
                  )
              );
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'Failed to cancel delayed email on read: %', SQLERRM;
        END;

    END IF;

    RETURN NEW;
END;
$$;

GRANT EXECUTE ON FUNCTION public.trg_fn_notifications_cancel_delayed_email_on_read() TO authenticated, service_role, anon;

DROP TRIGGER IF EXISTS trg_notifications_cancel_delayed_email_on_read ON public.notifications;
CREATE TRIGGER trg_notifications_cancel_delayed_email_on_read
    AFTER UPDATE OF is_read, read_at ON public.notifications
    FOR EACH ROW
    EXECUTE FUNCTION public.trg_fn_notifications_cancel_delayed_email_on_read();

-- 6. RPC: Atomic Conversation Read & Email Cancellation
CREATE OR REPLACE FUNCTION public.mark_conversation_read_and_cancel_emails(
    p_match_id uuid,
    p_user_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_user_id uuid;
    v_msgs_updated integer := 0;
    v_notifs_updated integer := 0;
    v_emails_cancelled integer := 0;
BEGIN
    -- 1. Resolve user ID
    v_user_id := COALESCE(p_user_id, auth.uid());
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    IF auth.role() <> 'service_role' AND auth.uid() <> v_user_id THEN
        RAISE EXCEPTION 'Not authorized';
    END IF;

    -- 2. Validate participant membership
    IF NOT EXISTS (
        SELECT 1 FROM public.matches
        WHERE id = p_match_id
          AND (user1_id = v_user_id OR user2_id = v_user_id)
    ) THEN
        RAISE EXCEPTION 'User is not a participant in this conversation';
    END IF;

    -- 3. Mark messages as read in public.messages
    UPDATE public.messages
    SET is_read = true,
        read_at = COALESCE(read_at, now()),
        seen_at = COALESCE(seen_at, now())
    WHERE match_id = p_match_id
      AND sender_id <> v_user_id
      AND COALESCE(is_read, false) = false;
    GET DIAGNOSTICS v_msgs_updated = ROW_COUNT;

    -- 4. Mark notifications as read in public.notifications
    UPDATE public.notifications
    SET is_read = true,
        read_at = COALESCE(read_at, now()),
        seen_at = COALESCE(seen_at, now()),
        updated_at = now()
    WHERE user_id = v_user_id
      AND (
          match_id = p_match_id
          OR conversation_id = p_match_id
          OR (metadata->>'match_id') = p_match_id::text
          OR (metadata->>'conversation_id') = p_match_id::text
      )
      AND COALESCE(is_read, false) = false;
    GET DIAGNOSTICS v_notifs_updated = ROW_COUNT;

    -- 5. Cancel pending email queue entries
    UPDATE public.notification_email_queue
    SET status = 'cancelled_read',
        cancelled_at = now(),
        updated_at = now()
    WHERE user_id = v_user_id
      AND status = 'pending'
      AND (
          dedupe_key = 'email:chat:' || v_user_id::text || ':' || p_match_id::text
          OR notification_id IN (
              SELECT id FROM public.notifications
              WHERE user_id = v_user_id
                AND (match_id = p_match_id OR conversation_id = p_match_id)
          )
      );
    GET DIAGNOSTICS v_emails_cancelled = ROW_COUNT;

    RETURN jsonb_build_object(
        'success', true,
        'match_id', p_match_id,
        'user_id', v_user_id,
        'messages_marked_read', v_msgs_updated,
        'notifications_marked_read', v_notifs_updated,
        'emails_cancelled', v_emails_cancelled
    );
END;
$$;

GRANT EXECUTE ON FUNCTION public.mark_conversation_read_and_cancel_emails(uuid, uuid) TO authenticated, service_role;

-- 7. RPC: Atomically Claim Batch for Queue Worker (FOR UPDATE SKIP LOCKED)
CREATE OR REPLACE FUNCTION public.claim_notification_email_batch(
    p_limit integer DEFAULT 25
)
RETURNS TABLE (
    id uuid,
    notification_id uuid,
    user_id uuid,
    actor_id uuid,
    recipient_email text,
    category text,
    type text,
    title text,
    content text,
    body text,
    action_url text,
    dedupe_key text,
    status text,
    scheduled_for timestamptz,
    retry_count integer,
    max_retries integer,
    metadata jsonb,
    created_at timestamptz,
    updated_at timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    RETURN QUERY
    WITH due_items AS (
        SELECT q.id AS due_id
        FROM public.notification_email_queue q
        WHERE q.status = 'pending'
          AND q.scheduled_for <= now()
        ORDER BY q.scheduled_for ASC
        LIMIT LEAST(GREATEST(p_limit, 1), 50)
        FOR UPDATE SKIP LOCKED
    ),
    claimed_items AS (
        UPDATE public.notification_email_queue target
        SET status = 'processing',
            updated_at = now()
        FROM due_items
        WHERE target.id = due_items.due_id
        RETURNING target.*
    )
    SELECT
        c.id,
        c.notification_id,
        c.user_id,
        c.actor_id,
        c.recipient_email,
        c.category,
        c.type,
        c.title,
        c.content,
        c.body,
        c.action_url,
        c.dedupe_key,
        c.status,
        c.scheduled_for,
        c.retry_count,
        c.max_retries,
        c.metadata,
        c.created_at,
        c.updated_at
    FROM claimed_items c;
END;
$$;

GRANT EXECUTE ON FUNCTION public.claim_notification_email_batch(integer) TO service_role;

-- 8. RPC: Worker Batch Fetch for send-notification-email (Fallback/Inspection)
CREATE OR REPLACE FUNCTION public.fetch_pending_notification_emails(
    p_batch_size integer DEFAULT 20
)
RETURNS TABLE (
    queue_id uuid,
    notification_id uuid,
    user_id uuid,
    actor_id uuid,
    category text,
    type text,
    title text,
    content text,
    action_url text,
    dedupe_key text,
    retry_count integer,
    metadata jsonb,
    is_notification_read boolean,
    recipient_email text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    RETURN QUERY
    SELECT
        q.id AS queue_id,
        q.notification_id,
        q.user_id,
        q.actor_id,
        q.category,
        q.type,
        q.title,
        q.content,
        q.action_url,
        q.dedupe_key,
        q.retry_count,
        q.metadata,
        COALESCE(n.is_read, false) AS is_notification_read,
        COALESCE(q.recipient_email, u.email::text) AS recipient_email
    FROM public.notification_email_queue q
    LEFT JOIN public.notifications n ON q.notification_id = n.id
    LEFT JOIN auth.users u ON q.user_id = u.id
    WHERE q.status = 'pending'
      AND q.scheduled_for <= now()
    ORDER BY q.scheduled_for ASC
    LIMIT LEAST(GREATEST(p_batch_size, 1), 100);
END;
$$;

GRANT EXECUTE ON FUNCTION public.fetch_pending_notification_emails(integer) TO service_role;

COMMENT ON TABLE public.notification_email_queue IS 'Queue of delayed transactional emails with 15-minute unread grace window.';
COMMENT ON FUNCTION public.mark_conversation_read_and_cancel_emails IS 'Atomically marks messages & notifications as read, and cancels pending delayed emails for a conversation.';
COMMENT ON FUNCTION public.claim_notification_email_batch IS 'Claims a batch of due pending emails atomically for worker processing via FOR UPDATE SKIP LOCKED.';


-- -----------------------------------------------------------------------------
-- [Migration: 20261008200000_include_photos_in_profile_viewers.sql]
-- -----------------------------------------------------------------------------
-- ============================================================================
-- Migration: Include profile photos and timestamps in get_profile_viewers_secure
-- Ensures profile_photos and photo_updated_at are projected so getAvatarUrl
-- resolves authentic photos for viewers on web and mobile clients.
-- ============================================================================

create or replace function public.get_profile_viewers_secure(p_limit integer default 20)
returns jsonb
language plpgsql
security definer
set search_path to ''
as $$
declare
    v_user_id uuid := auth.uid();
    v_is_premium boolean;
    v_total integer;
    v_items jsonb;
begin
    if v_user_id is null then
        return jsonb_build_object('success', false, 'error', 'Not authenticated');
    end if;

    v_is_premium := public.has_entitlement(v_user_id, 'see_profile_viewers')
        or public.has_entitlement(v_user_id, 'premium');

    select count(*)::integer
    into v_total
    from public.profile_views pv
    where pv.profile_owner_id = v_user_id;

    if not v_is_premium then
        select coalesce(jsonb_agg(item), '[]'::jsonb)
        into v_items
        from (
            select jsonb_build_object(
                'created_at', pv.created_at,
                'locked', true
            ) as item
            from public.profile_views pv
            where pv.profile_owner_id = v_user_id
            order by pv.created_at desc
            limit greatest(1, least(coalesce(p_limit, 20), 50))
        ) locked_items;

        return jsonb_build_object(
            'success', true,
            'premium', false,
            'upgrade_required', v_total > 0,
            'total_count', v_total,
            'items', coalesce(v_items, '[]'::jsonb)
        );
    end if;

    select coalesce(jsonb_agg(item), '[]'::jsonb)
    into v_items
    from (
        select jsonb_build_object(
            'id', pv.id,
            'created_at', pv.created_at,
            'viewer', jsonb_build_object(
                'id', p.id,
                'full_name', p.full_name,
                'avatar_url', p.avatar_url,
                'profile_photos', p.profile_photos,
                'photo_updated_at', p.photo_updated_at,
                'university', p.university,
                'last_active', p.last_active
            ),
            'locked', false
        ) as item
        from public.profile_views pv
        join public.profiles p on p.id = pv.viewer_id
        where pv.profile_owner_id = v_user_id
        order by pv.created_at desc
        limit greatest(1, least(coalesce(p_limit, 20), 50))
    ) unlocked_items;

    return jsonb_build_object(
        'success', true,
        'premium', true,
        'upgrade_required', false,
        'total_count', v_total,
        'items', coalesce(v_items, '[]'::jsonb)
    );
end;
$$;

grant execute on function public.get_profile_viewers_secure(integer) to authenticated;


-- -----------------------------------------------------------------------------
-- [Migration: 20261009180000_protect_profile_trust_badges.sql]
-- -----------------------------------------------------------------------------
-- Migration: 20261009180000_protect_profile_trust_badges.sql
-- Description: Authoritative engine-level defense against unauthorized badge & trust status tampering.
-- Target: public.profiles (is_verified, photo_verified, ai_verification_status, etc.)

-- 1. Ensure photo_verified column exists with default false
ALTER TABLE public.profiles 
  ADD COLUMN IF NOT EXISTS photo_verified boolean DEFAULT false;

-- 2. Create authoritative trigger function
CREATE OR REPLACE FUNCTION public.enforce_profile_trust_field_integrity()
RETURNS trigger
LANGUAGE plpgsql
VOLATILE
SECURITY INVOKER
SET search_path = public, extensions, pg_catalog
AS $$
DECLARE
    v_is_authorized boolean := false;
    v_is_admin boolean := false;
    v_jwt_role text := '';
BEGIN
    -- Resolve JWT role safely
    BEGIN
        v_jwt_role := COALESCE(
            auth.role(),
            auth.jwt() ->> 'role',
            current_setting('request.jwt.claim.role', true),
            ''
        );
    EXCEPTION WHEN OTHERS THEN
        v_jwt_role := '';
    END;

    -- Resolve admin status safely
    BEGIN
        v_is_admin := public.is_app_admin();
    EXCEPTION WHEN OTHERS THEN
        v_is_admin := false;
    END;

    -- Evaluate caller authorization:
    -- 1. PostgreSQL superuser / maintenance / database migrations (postgres, supabase_admin)
    -- 2. SECURITY DEFINER functions owned by postgres (e.g. admin_set_user_status)
    -- 3. Supabase Edge Functions / Backend Workers operating under service_role
    -- 4. Authorized Application Administrators
    IF current_user IN ('postgres', 'service_role', 'supabase_admin')
       OR v_jwt_role = 'service_role'
       OR v_is_admin THEN
        v_is_authorized := true;
    END IF;

    -- -------------------------------------------------------------------------
    -- INSERT PROTECTION: Force safe initial trust defaults for non-authorized callers
    -- -------------------------------------------------------------------------
    IF TG_OP = 'INSERT' THEN
        IF NOT v_is_authorized THEN
            NEW.is_verified := false;
            NEW.photo_verified := false;
            NEW.ai_verification_status := 'not_started';
            NEW.ai_verification_score := NULL;
            NEW.ai_photo_origin := NULL;
            NEW.ai_reviewed_at := NULL;
            NEW.ai_review_summary := NULL;
            NEW.ai_review_flags := ARRAY[]::text[];
            NEW.is_banned := false;
            NEW.is_shadow_banned := false;
            NEW.is_premium := false;
        END IF;
        RETURN NEW;
    END IF;

    -- -------------------------------------------------------------------------
    -- UPDATE PROTECTION: Revert unauthorized changes to trust & privilege fields
    -- -------------------------------------------------------------------------
    IF TG_OP = 'UPDATE' THEN
        IF NOT v_is_authorized THEN
            -- Check if any protected field was tampered with
            IF NEW.is_verified IS DISTINCT FROM OLD.is_verified
               OR NEW.photo_verified IS DISTINCT FROM OLD.photo_verified
               OR NEW.ai_verification_status IS DISTINCT FROM OLD.ai_verification_status
               OR NEW.ai_verification_score IS DISTINCT FROM OLD.ai_verification_score
               OR NEW.ai_photo_origin IS DISTINCT FROM OLD.ai_photo_origin
               OR NEW.ai_reviewed_at IS DISTINCT FROM OLD.ai_reviewed_at
               OR NEW.ai_review_summary IS DISTINCT FROM OLD.ai_review_summary
               OR NEW.ai_review_flags IS DISTINCT FROM OLD.ai_review_flags
               OR NEW.is_banned IS DISTINCT FROM OLD.is_banned
               OR NEW.is_shadow_banned IS DISTINCT FROM OLD.is_shadow_banned
               OR NEW.is_premium IS DISTINCT FROM OLD.is_premium THEN

                -- Forcibly revert all protected fields to their pre-existing values
                NEW.is_verified := OLD.is_verified;
                NEW.photo_verified := OLD.photo_verified;
                NEW.ai_verification_status := OLD.ai_verification_status;
                NEW.ai_verification_score := OLD.ai_verification_score;
                NEW.ai_photo_origin := OLD.ai_photo_origin;
                NEW.ai_reviewed_at := OLD.ai_reviewed_at;
                NEW.ai_review_summary := OLD.ai_review_summary;
                NEW.ai_review_flags := OLD.ai_review_flags;
                NEW.is_banned := OLD.is_banned;
                NEW.is_shadow_banned := OLD.is_shadow_banned;
                NEW.is_premium := OLD.is_premium;
            END IF;
        END IF;
        RETURN NEW;
    END IF;

    RETURN NEW;
END;
$$;

-- 3. Bind trigger to public.profiles
DROP TRIGGER IF EXISTS trg_enforce_profile_trust_integrity ON public.profiles;

CREATE TRIGGER trg_enforce_profile_trust_integrity
    BEFORE INSERT OR UPDATE ON public.profiles
    FOR EACH ROW
    EXECUTE FUNCTION public.enforce_profile_trust_field_integrity();

-- 4. Execution grants: Restrict execution to authenticated and service_role
REVOKE ALL ON FUNCTION public.enforce_profile_trust_field_integrity() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.enforce_profile_trust_field_integrity() TO authenticated, service_role;


