        NULLIF(current_setting('app.supabase_service_key', true), ''),
        (SELECT value #>> '{}' FROM public.app_config WHERE key = 'supabase_service_role_key'),
        (SELECT value #>> '{}' FROM public.app_config WHERE key = 'supabase_anon_key'),
        'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImdlZG95b2xlb3NjZ3hnZHFzenpjIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzA4MjQ4ODcsImV4cCI6MjA4NjQwMDg4N30.pVnlTBOwxYSFgC0fQ2Wo1oEsrBWak6X2FBBeNGariys'
    );

    -- 4. Assemble dual-format payload compatible with both legacy and modern OneSignal edge functions
    v_payload := jsonb_build_object(
        'type', 'INSERT',
        'table', 'notifications',
        'schema', 'public',
        'userId', COALESCE(NEW.user_id, NEW.recipient_id),
        'externalUserIds', jsonb_build_array(COALESCE(NEW.user_id, NEW.recipient_id)),
        'title', NEW.title,
        'content', NEW.content,
        'headings', jsonb_build_object('en', NEW.title),
        'contents', jsonb_build_object('en', NEW.content),
        'category', NEW.category,
        'priority', NEW.priority,
        'data', jsonb_build_object(
            'notification_id', NEW.id,
            'type', NEW.type,
            'category', NEW.category,
            'entity_id', NEW.entity_id,
            'match_id', NEW.match_id,
            'conversation_id', NEW.conversation_id,
            'deep_link', NEW.deep_link
        ),
        'record', jsonb_build_object(
            'id', NEW.id,
            'user_id', COALESCE(NEW.user_id, NEW.recipient_id),
            'recipient_id', COALESCE(NEW.recipient_id, NEW.user_id),
            'actor_id', COALESCE(NEW.actor_id, NEW.sender_id),
            'sender_id', COALESCE(NEW.sender_id, NEW.actor_id),
            'type', NEW.type,
            'category', NEW.category,
            'title', NEW.title,
            'content', NEW.content,
            'metadata', COALESCE(NEW.metadata, '{}'::jsonb),
            'deep_link', NEW.deep_link,
            'priority', NEW.priority,
            'group_key', NEW.group_key,
            'dedupe_key', NEW.dedupe_key,
            'created_at', NEW.created_at
        )
    );

    v_headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || v_service_key,
        'apikey', v_service_key
    );

    -- 5. Exception containment block: invoke net.http_post asynchronously
    BEGIN
        IF EXISTS (
            SELECT 1 FROM pg_proc p
            JOIN pg_namespace n ON p.pronamespace = n.oid
            WHERE n.nspname = 'net' AND p.proname = 'http_post'
        ) THEN
            PERFORM net.http_post(
                url := v_edge_url,
                body := v_payload,
                headers := v_headers,
                timeout_milliseconds := 5000
            );
        END IF;
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'Push trigger dispatch failed: %', SQLERRM;
    END;

    RETURN NEW;
END;
$$;

-- Grant execution rights
GRANT EXECUTE ON FUNCTION public.trg_fn_notifications_push_dispatch() TO authenticated, service_role, anon;

-- Reattach trigger
DROP TRIGGER IF EXISTS trg_notifications_push_dispatch ON public.notifications;
CREATE TRIGGER trg_notifications_push_dispatch
AFTER INSERT ON public.notifications
FOR EACH ROW
EXECUTE FUNCTION public.trg_fn_notifications_push_dispatch();

-- 3. Campus Confessions Broadcast Trigger: Notify peers on the same campus outside the app
CREATE OR REPLACE FUNCTION public.trg_fn_broadcast_campus_confession()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_campus text;
    v_snippet text;
    v_author_id uuid;
BEGIN
    v_campus := COALESCE(NEW.university, '');
    v_author_id := NEW.user_id;

    IF v_campus IS NULL OR v_campus = '' THEN
        RETURN NEW;
    END IF;

    v_snippet := CASE 
        WHEN length(NEW.content) > 55 THEN substring(NEW.content from 1 for 52) || '...'
        ELSE NEW.content
    END;

    -- Broadcast to active students on the same campus (up to 50 students per confession)
    INSERT INTO public.notifications (
        user_id,
        actor_id,
        type,
        category,
        title,
        content,
        deep_link,
        priority,
        metadata
    )
    SELECT 
        p.id,
        NULL,
        'confession',
        'social',
        '🔥 New Campus Secret (' || v_campus || ') 🤫',
        v_snippet,
        '/confessions',
        'normal',
        jsonb_build_object(
            'is_anonymous', true,
            'campus', v_campus,
            'confession_id', NEW.id,
            'url', '/confessions'
        )
    FROM public.profiles p
    WHERE p.university = v_campus
      AND p.id != v_author_id
      AND p.confession_notifications IS NOT FALSE
      AND p.push_notifications IS NOT FALSE
      AND (p.last_seen_at IS NULL OR p.last_seen_at >= now() - interval '14 days')
    ORDER BY p.last_seen_at DESC NULLS LAST
    LIMIT 50;

    RETURN NEW;
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Campus confession broadcast failed: %', SQLERRM;
    RETURN NEW;
END;
$$;

GRANT EXECUTE ON FUNCTION public.trg_fn_broadcast_campus_confession() TO authenticated, service_role, anon;

DROP TRIGGER IF EXISTS trg_confessions_broadcast_campus ON public.confessions;
CREATE TRIGGER trg_confessions_broadcast_campus
AFTER INSERT ON public.confessions
FOR EACH ROW
EXECUTE FUNCTION public.trg_fn_broadcast_campus_confession();

-- 4. Automated Profile Visibility & Match Retention Reminders
CREATE OR REPLACE FUNCTION public.dispatch_campus_retention_reminders()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_dispatched int := 0;
BEGIN
    -- 1. Profile completion reminder: students with missing bio or avatar
    INSERT INTO public.notifications (
        user_id,
        type,
        category,
        title,
        content,
        deep_link,
        priority,
        metadata
    )
    SELECT 
        p.id,
        'profile_reminder',
        'profile_activity',
        '👀 Boost Your Campus Match Visibility!',
        'Profiles with completed photos and bios receive 4x more mutual matches. Tap to finish your profile!',
        '/profile',
        'normal',
        jsonb_build_object('url', '/profile', 'prompt', 'profile_completion')
    FROM public.profiles p
    WHERE (p.bio IS NULL OR length(p.bio) < 10 OR p.avatar_url IS NULL)
      AND p.push_notifications IS NOT FALSE
      AND NOT EXISTS (
          SELECT 1 FROM public.notifications n
          WHERE n.user_id = p.id
            AND n.type = 'profile_reminder'
            AND n.created_at >= now() - interval '3 days'
      )
    LIMIT 25;

    GET DIAGNOSTICS v_dispatched = ROW_COUNT;

    RETURN jsonb_build_object('success', true, 'dispatched', v_dispatched);
END;
$$;

GRANT EXECUTE ON FUNCTION public.dispatch_campus_retention_reminders() TO authenticated, service_role, anon;


-- -----------------------------------------------------------------------------
-- [Migration: 20261013030000_block_off_platform_contact_sharing.sql]
-- -----------------------------------------------------------------------------
-- Migration: 20261013030000_block_off_platform_contact_sharing.sql
-- Description: Server-authoritative guard against off-platform contact sharing in chat messages.
-- Standard users cannot share phone numbers, social media handles, or external links.
-- Subscribed Elite Ultra VIP members (15k/mo) have complete exemption to share/ask contacts without safeguards.

CREATE OR REPLACE FUNCTION public.check_message_off_platform_contact()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_is_ultra boolean := false;
    v_plan text;
    v_clean text;
BEGIN
    -- Only evaluate text messages
    IF NEW.type IS DISTINCT FROM 'text' OR NEW.content IS NULL OR length(trim(NEW.content)) = 0 THEN
        RETURN NEW;
    END IF;

    -- Check if sender has active Elite Ultra VIP status
    SELECT 
        COALESCE(p.is_ultra, false) OR COALESCE(s.plan_type = 'ultra', false) OR COALESCE(s.tier = 'ultra', false)
    INTO v_is_ultra
    FROM public.profiles p
    LEFT JOIN public.subscriptions s ON s.user_id = p.id AND s.status = 'active'
    WHERE p.id = NEW.sender_id;

    -- Elite Ultra members bypass all contact-sharing safeguards
    IF v_is_ultra IS TRUE THEN
        RETURN NEW;
    END IF;

    -- Also check metadata flag if client passed verified session claim
    IF (NEW.metadata->>'isUltraSender')::boolean IS TRUE THEN
        RETURN NEW;
    END IF;

    v_clean := lower(NEW.content);

    -- 1. Block external contact links & domains
    IF v_clean ~* '(wa\.me|chat\.whatsapp\.com|api\.whatsapp\.com|t\.me|telegram\.me|instagram\.com|instagr\.am|snapchat\.com|tiktok\.com|vm\.tiktok\.com|discord\.gg|linktr\.ee|beacons\.ai|bit\.ly|tinyurl\.com)' THEN
        RAISE EXCEPTION 'OFF_PLATFORM_CONTACT_BLOCKED: External messenger links are restricted. Upgrade to Elite Ultra (15k) to share external links.';
    END IF;

    -- 2. Block standard Nigerian phone numbers and international format digits (10-14 digits)
    -- Catches: 0803..., 090..., 070..., 081..., +234..., 0 8 0 3..., 0803-123-4567, etc.
    IF regexp_replace(v_clean, '[^0-9]', '', 'g') ~ '(?:234|0)[789][01][0-9]{7,8}' OR
       length(regexp_replace(v_clean, '[^0-9]', '', 'g')) >= 10 THEN
        RAISE EXCEPTION 'OFF_PLATFORM_CONTACT_BLOCKED: Phone numbers are restricted in chat. Upgrade to Elite Ultra (15k) to exchange contacts freely.';
    END IF;

    -- 3. Block email addresses
    IF v_clean ~ '[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}' THEN
        RAISE EXCEPTION 'OFF_PLATFORM_CONTACT_BLOCKED: Email addresses cannot be shared. Upgrade to Elite Ultra (15k) to exchange contacts freely.';
    END IF;

    -- 4. Block explicit off-platform phrases & handle exchanges
    IF v_clean ~* '\b(my|your|ur|yr)\s+(whatsapp|whatsap|watsapp|ig|insta|instagram|snap|snapchat|tiktok|telegram|digits|phone number|numba|nomba|line)\b' OR
       v_clean ~* '\b(drop|send|give|share)\s+(your|ur|my)\s+(digits|number|whatsapp|ig|snap|handle|contact)\b' OR
       v_clean ~* '\b(add me on|follow me on|hmu on|whatsapp me|snap me)\s+(whatsapp|snap|snapchat|ig|insta|instagram|tiktok|telegram|x)\b' OR
       v_clean ~* '\b(flash|beep)\s+me\b' OR
       v_clean ~* '\b(drop|send)\s+(your|ur)\s+(opay|palmpay)\b' OR
       v_clean ~* '\b(move|talk|chat)\s+(off|outside)\s+(this|the)\s+app\b' THEN
        RAISE EXCEPTION 'OFF_PLATFORM_CONTACT_BLOCKED: Sharing off-platform contacts is restricted. Upgrade to Elite Ultra (15k) to ask any question without safeguards.';
    END IF;

    RETURN NEW;
END;
$$;

-- Drop existing trigger if present, then bind trigger to public.messages
DROP TRIGGER IF EXISTS trg_check_message_off_platform_contact ON public.messages;

CREATE TRIGGER trg_check_message_off_platform_contact
BEFORE INSERT OR UPDATE OF content ON public.messages
FOR EACH ROW
EXECUTE FUNCTION public.check_message_off_platform_contact();


