-- [Migration: 20261019140000_unify_face_verification_integrity.sql]
-- -----------------------------------------------------------------------------
-- Migration: 20261019120000_unify_face_verification_integrity.sql
-- Description:
-- 1. Unify admin_set_user_status('verify') to synchronize both is_verified and photo_verified (fixes RC-4).
-- 2. Reset is_verified and photo_verified in promote_validated_avatar when slot 0 (primary photo) is replaced.
-- 3. Unify get_public_ask_profile and get_matched_profile to project unified verification status (is_verified OR photo_verified).

-- ============================================================================
-- 1. ADMIN SET USER STATUS (Synchronize is_verified + photo_verified)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.admin_set_user_status(
  p_user_id uuid,
  p_action text,
  p_status boolean,
  p_reason text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_action text := lower(trim(coalesce(p_action, '')));
  v_reason text := trim(coalesce(p_reason, ''));
  v_target public.profiles%rowtype;
  v_audit_action text;
BEGIN
  IF NOT public.admin_has_permission('users:moderate') THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF auth.uid() = p_user_id AND v_action IN ('ban', 'shadow') AND p_status IS TRUE THEN
    RAISE EXCEPTION 'Admins cannot ban or shadow-ban themselves';
  END IF;

  IF v_action NOT IN ('ban', 'shadow', 'verify') THEN
    RAISE EXCEPTION 'Invalid user status action';
  END IF;

  IF length(v_reason) < 5 THEN
    RAISE EXCEPTION 'Admin reason is required';
  END IF;

  SELECT *
  INTO v_target
  FROM public.profiles
  WHERE id = p_user_id;

  IF v_target.id IS NULL THEN
    RAISE EXCEPTION 'User profile not found';
  END IF;

  IF v_action = 'ban' THEN
    UPDATE public.profiles
    SET is_banned = p_status
    WHERE id = p_user_id;
    v_audit_action := CASE WHEN p_status THEN 'admin_ban_user' ELSE 'admin_unban_user' END;
  ELSIF v_action = 'shadow' THEN
    UPDATE public.profiles
    SET is_shadow_banned = p_status
    WHERE id = p_user_id;
    v_audit_action := CASE WHEN p_status THEN 'admin_shadow_user' ELSE 'admin_unshadow_user' END;
  ELSE
    UPDATE public.profiles
    SET is_verified = p_status,
        photo_verified = p_status,
        ai_verification_status = CASE WHEN p_status THEN 'verified' ELSE 'not_started' END,
        ai_reviewed_at = now(),
        ai_review_summary = CASE
          WHEN p_status THEN 'Verified by administrator.'
          ELSE 'Verification removed by administrator.'
        END
    WHERE id = p_user_id;
    v_audit_action := CASE WHEN p_status THEN 'admin_verify_user' ELSE 'admin_unverify_user' END;
  END IF;

  PERFORM public.admin_write_audit_log(
    v_audit_action,
    'profile',
    p_user_id,
    jsonb_build_object(
      'status', p_status,
      'reason', v_reason,
      'target_email', v_target.email,
      'target_name', v_target.full_name
    )
  );

  RETURN jsonb_build_object('ok', true, 'action', v_action, 'status', p_status, 'user_id', p_user_id);
END;
$function$;

-- ============================================================================
-- 2. PROMOTE VALIDATED AVATAR (Reset badge when primary photo Slot 0 changes)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.promote_validated_avatar(
    p_user_id UUID,
    p_photo_url TEXT,
    p_slot_index INT DEFAULT 0
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_caller_id UUID;
    v_current_photos TEXT[];
    v_new_photos TEXT[];
    v_slot INT;
BEGIN
    v_caller_id := auth.uid();
    IF v_caller_id IS NOT NULL AND v_caller_id != p_user_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'Unauthorized profile modification');
    END IF;

    v_slot := coalesce(p_slot_index, 0);

    SELECT profile_photos INTO v_current_photos
    FROM public.profiles
    WHERE id = p_user_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Profile not found');
    END IF;

    v_new_photos := coalesce(v_current_photos, ARRAY[]::TEXT[]);
    WHILE array_length(v_new_photos, 1) IS NULL OR array_length(v_new_photos, 1) <= v_slot LOOP
        v_new_photos := array_append(v_new_photos, NULL::TEXT);
    END LOOP;

    v_new_photos[v_slot + 1] := p_photo_url;

    IF v_slot = 0 THEN
        UPDATE public.profiles
        SET avatar_url = p_photo_url,
            profile_photos = v_new_photos,
            is_verified = false,
            photo_verified = false,
            ai_verification_status = 'not_started',
            ai_review_summary = 'Primary profile photo updated. Please complete a quick live selfie verification check to reactivate your Verified badge.',
            photo_updated_at = now(),
            updated_at = now()
        WHERE id = p_user_id;
    ELSE
        UPDATE public.profiles
        SET profile_photos = v_new_photos,
            photo_updated_at = now(),
            updated_at = now()
        WHERE id = p_user_id;
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'user_id', p_user_id,
        'avatar_url', p_photo_url,
        'slot', v_slot,
        'verification_reset', (v_slot = 0)
    );
END;
$$;

GRANT EXECUTE ON FUNCTION public.promote_validated_avatar(UUID, TEXT, INT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.promote_validated_avatar(UUID, TEXT, INT) TO service_role;

-- ============================================================================
-- 3. PUBLIC ASK PROFILE RPC (Include unified is_verified & photo_verified)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_public_ask_profile(p_username_or_id text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_clean text;
    v_is_uuid boolean;
    v_profile record;
BEGIN
    IF p_username_or_id IS NULL OR length(trim(p_username_or_id)) = 0 THEN
        RETURN NULL;
    END IF;

    v_clean := lower(trim(leading '@' from trim(p_username_or_id)));
    v_is_uuid := p_username_or_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

    IF v_is_uuid THEN
        SELECT
            id,
            full_name,
            username,
            avatar_url,
            university,
            (COALESCE(is_verified, false) OR COALESCE(photo_verified, false)) AS is_verified,
            COALESCE(photo_verified, false) AS photo_verified,
            bio,
            video_url
        INTO v_profile
        FROM public.profiles
        WHERE id = p_username_or_id::uuid
          AND COALESCE(is_banned, false) = false
        LIMIT 1;
    ELSE
        SELECT
            id,
            full_name,
            username,
            avatar_url,
            university,
            (COALESCE(is_verified, false) OR COALESCE(photo_verified, false)) AS is_verified,
            COALESCE(photo_verified, false) AS photo_verified,
            bio,
            video_url
        INTO v_profile
        FROM public.profiles
        WHERE lower(username) = v_clean
          AND COALESCE(is_banned, false) = false
        LIMIT 1;
    END IF;

    IF v_profile.id IS NULL THEN
        RETURN NULL;
    END IF;

    RETURN to_jsonb(v_profile);
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_public_ask_profile(text) TO anon, authenticated, service_role;

-- ============================================================================
-- 4. GET MATCHED PROFILE RPC (Unify is_verified OR photo_verified)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.get_matched_profile(p_profile_id uuid)
RETURNS TABLE (
    id uuid,
    full_name text,
    username text,
    gender text,
    age integer,
    university text,
    faculty text,
    department text,
    level text,
    bio text,
    avatar_url text,
    photos text[],
    profile_photos text[],
    interests jsonb,
    intro_prompt text,
    voice_intro_url text,
    anthem text,
    attraction_goal text,
    is_verified boolean,
    completion_score integer,
    last_seen_at timestamp with time zone,
    last_active timestamp with time zone,
    is_live boolean
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO ''
AS $$
DECLARE
    v_user_id uuid := auth.uid();
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'not_authenticated';
    END IF;

    IF p_profile_id IS NULL OR p_profile_id = v_user_id THEN
        RAISE EXCEPTION 'invalid_profile';
    END IF;

    RETURN QUERY
    SELECT
        p.id,
        p.full_name,
        p.username,
        p.gender,
        p.age,
        p.university,
        p.faculty,
        p.department,
        p.level,
        p.bio,
        p.avatar_url,
        p.photos,
        p.profile_photos,
        p.interests,
        p.intro_prompt,
        p.voice_intro_url,
        p.anthem,
        p.attraction_goal,
        (coalesce(p.is_verified, false) OR coalesce(p.photo_verified, false)) AS is_verified,
        coalesce(p.completion_score, 0) AS completion_score,
        p.last_seen_at,
        p.last_active,
        coalesce(p.last_active, p.last_seen_at) > now() - interval '15 minutes' AS is_live
    FROM public.profiles p
    WHERE p.id = p_profile_id
      AND coalesce(p.is_banned, false) = false
      AND coalesce(p.is_shadow_banned, false) = false
      AND coalesce(p.is_blocked, false) = false
      AND coalesce(p.incognito_mode, false) = false
      AND EXISTS (
          SELECT 1
          FROM public.matches m
          WHERE m.user_ids @> array[v_user_id, p_profile_id]::uuid[]
      )
      AND NOT EXISTS (
          SELECT 1
          FROM public.reports r
          WHERE (
              (r.reporter_id = v_user_id AND r.reported_id = p_profile_id)
              OR (r.reporter_id = p_profile_id AND r.reported_id = v_user_id)
          )
          AND coalesce(r.status, 'pending') <> 'dismissed'
      );
END;
$$;

REVOKE ALL ON FUNCTION public.get_matched_profile(uuid) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.get_matched_profile(uuid) TO authenticated;

NOTIFY pgrst, 'reload schema';


-- -----------------------------------------------------------------------------
-- [Migration: 20261020120000_critical_security_audit_hardening.sql]
-- -----------------------------------------------------------------------------
-- ============================================================================
-- Migration: 20261020120000_critical_security_audit_hardening.sql
-- Description:
--   Comprehensive security hardening addressing findings from red-team audit:
--   1. Fix referral milestone infinite money glitch (VULN-CD-001):
--      - Adds referral_milestones_awarded integer[] to public.wallets.
--      - Rewrites process_referral_milestones with FOR UPDATE locking and
--        idempotent milestone tier tracking.
--   2. Fix unconfirmed admin email spoofing (VULN-CD-004):
--      - Hardens is_app_admin(), admin_is_owner(), and admin_has_permission()
--        to require email_confirmed_at IS NOT NULL.
--   3. Fix pending-avatars storage isolation (VULN-CD-005):
--      - Enforces (storage.foldername(name))[1] = auth.uid()::text on upload and update.
--   4. Prevent self-gifting in process_gift_purchase (VULN-CD-007).
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. REFERRAL MILESTONE INFINITE MONEY REMEDIATION (VULN-CD-001)
-- ----------------------------------------------------------------------------

-- Ensure referral_milestones_awarded array exists on public.wallets
ALTER TABLE public.wallets
    ADD COLUMN IF NOT EXISTS referral_milestones_awarded integer[] DEFAULT '{}';

CREATE OR REPLACE FUNCTION public.process_referral_milestones(p_referrer_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $$
declare
    v_wallet_id uuid;
    v_milestones integer[];
    v_count bigint;
    v_milestone_tier integer;
    v_reward numeric := 0;
begin
    -- 1. Strict authorization: caller must be the referrer
    if auth.uid() is null or auth.uid() <> p_referrer_id then
        return jsonb_build_object('success', false, 'error', 'Not authorized');
    end if;

    -- 2. Lock wallet row FOR UPDATE to eliminate concurrent double-claims
    select id, coalesce(referral_milestones_awarded, '{}')
    into v_wallet_id, v_milestones
    from public.wallets
    where user_id = p_referrer_id
    for update;

    if v_wallet_id is null then
        return jsonb_build_object('success', false, 'error', 'Wallet not found');
    end if;

    -- 3. Calculate total referrals (pending + rewarded)
    select count(*) into v_count
    from public.referrals
    where referrer_id = p_referrer_id and status in ('pending', 'rewarded');

    -- Calculate milestone tier (multiples of 10: 10, 20, 30...)
    v_milestone_tier := (v_count / 10)::integer * 10;

    -- 4. Check if this milestone tier has already been awarded
    if v_milestone_tier >= 10 and not (v_milestone_tier = any(v_milestones)) then
        v_reward := 3000;

        -- Atomically credit wallet and append milestone tier
        update public.wallets
        set available_balance = coalesce(available_balance, 0) + v_reward,
            total_earned = coalesce(total_earned, 0) + v_reward,
            referral_milestones_awarded = array_append(coalesce(referral_milestones_awarded, '{}'), v_milestone_tier),
            updated_at = now()
        where id = v_wallet_id;

        -- Record audit transaction
        insert into public.wallet_transactions
            (user_id, wallet_id, type, amount, status, description, metadata)
        values
            (
                p_referrer_id,
                v_wallet_id,
                'referral_milestone_bonus',
                v_reward,
                'completed',
                'Referral Milestone Bonus (' || v_milestone_tier || ' Friends)',
                jsonb_build_object('milestone_tier', v_milestone_tier, 'referral_count', v_count)
            );
    end if;

    -- 5. Mark pending referrals as rewarded
    update public.referrals
    set status = 'rewarded', rewarded_at = now()
    where referrer_id = p_referrer_id and status = 'pending';

    return jsonb_build_object(
        'success', true,
        'referral_count', v_count,
        'bonus_awarded', v_reward,
        'milestone_tier', v_milestone_tier
    );
end;
$$;

REVOKE ALL ON FUNCTION public.process_referral_milestones(uuid) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.process_referral_milestones(uuid) TO authenticated, service_role;

