-- ----------------------------------------------------------------------------
-- 4. PROCESS GIFT PURCHASE SELF-GIFTING RESTRICTION (VULN-CD-007)
-- ----------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.process_gift_purchase(
    p_sender_id uuid,
    p_receiver_id uuid,
    p_gift_id uuid,
    p_amount numeric
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $$
declare
    v_sender_wallet_id uuid;
    v_receiver_wallet_id uuid;
    v_balance numeric;
begin
    if auth.uid() is null or auth.uid() <> p_sender_id then
        return jsonb_build_object('success', false, 'error', 'Not authorized');
    end if;

    if p_sender_id = p_receiver_id then
        return jsonb_build_object('success', false, 'error', 'Cannot send gifts to yourself');
    end if;

    if p_amount is null or p_amount <= 0 then
        return jsonb_build_object('success', false, 'error', 'Invalid amount');
    end if;

    select id, available_balance
    into v_sender_wallet_id, v_balance
    from public.wallets
    where user_id = p_sender_id
    for update;

    if v_sender_wallet_id is null or coalesce(v_balance, 0) < p_amount then
        return jsonb_build_object('success', false, 'error', 'Insufficient balance');
    end if;

    select id
    into v_receiver_wallet_id
    from public.wallets
    where user_id = p_receiver_id;

    update public.wallets
    set available_balance = available_balance - p_amount,
        total_spent = coalesce(total_spent, 0) + p_amount,
        updated_at = now()
    where id = v_sender_wallet_id;

    insert into public.wallet_transactions
        (user_id, wallet_id, type, amount, status, description, metadata)
    values
        (
          p_sender_id,
          v_sender_wallet_id,
          'gift_purchase',
          p_amount,
          'completed',
          'Gift purchase',
          jsonb_build_object('gift_id', p_gift_id, 'receiver_id', p_receiver_id)
        );

    if v_receiver_wallet_id is not null then
        update public.wallets
        set available_balance = available_balance + (p_amount * 0.8),
            total_earned = coalesce(total_earned, 0) + (p_amount * 0.8),
            updated_at = now()
        where id = v_receiver_wallet_id;

        insert into public.wallet_transactions
            (user_id, wallet_id, type, amount, status, description, metadata)
        values
            (
              p_receiver_id,
              v_receiver_wallet_id,
              'gift_received',
              (p_amount * 0.8),
              'completed',
              'Gift received',
              jsonb_build_object('gift_id', p_gift_id, 'sender_id', p_sender_id)
            );
    end if;

    return jsonb_build_object('success', true, 'new_balance', v_balance - p_amount);
exception when others then
    return jsonb_build_object('success', false, 'error', sqlerrm);
end;
$$;

CREATE OR REPLACE FUNCTION public.process_gift_purchase(
    p_sender_id uuid,
    p_receiver_id uuid,
    p_gift_id text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $$
declare
    v_sender_wallet_id uuid;
    v_receiver_wallet_id uuid;
    v_gift_price numeric;
    v_gift_name text;
    v_sender_balance numeric;
begin
    if auth.uid() is null or auth.uid() <> p_sender_id then
        return jsonb_build_object('success', false, 'error', 'Not authorized');
    end if;

    if p_sender_id = p_receiver_id then
        return jsonb_build_object('success', false, 'error', 'Cannot send gifts to yourself');
    end if;

    select price, name into v_gift_price, v_gift_name
    from public.gifts
    where id = p_gift_id;

    if not found or v_gift_price is null or v_gift_price <= 0 then
        return jsonb_build_object('success', false, 'error', 'Invalid gift');
    end if;

    select id, available_balance into v_sender_wallet_id, v_sender_balance
    from public.wallets
    where user_id = p_sender_id
    for update;

    if v_sender_balance is null or v_sender_balance < v_gift_price then
        return jsonb_build_object('success', false, 'error', 'Insufficient balance');
    end if;

    select id into v_receiver_wallet_id
    from public.wallets
    where user_id = p_receiver_id;

    update public.wallets
    set available_balance = available_balance - v_gift_price,
        total_spent = total_spent + v_gift_price,
        updated_at = now()
    where id = v_sender_wallet_id;

    insert into public.wallet_transactions
        (user_id, wallet_id, type, amount, status, description, metadata)
    values
        (p_sender_id, v_sender_wallet_id, 'gift_purchase', v_gift_price, 'completed', 'Sent Gift: ' || v_gift_name, jsonb_build_object('receiver_id', p_receiver_id, 'gift_id', p_gift_id));

    if v_receiver_wallet_id is not null then
        update public.wallets
        set available_balance = available_balance + (v_gift_price * 0.5),
            total_earned = total_earned + (v_gift_price * 0.5),
            updated_at = now()
        where id = v_receiver_wallet_id;

        insert into public.wallet_transactions
            (user_id, wallet_id, type, amount, status, description, metadata)
        values
            (p_receiver_id, v_receiver_wallet_id, 'gift_received', (v_gift_price * 0.5), 'completed', 'Received Gift: ' || v_gift_name, jsonb_build_object('sender_id', p_sender_id, 'gift_id', p_gift_id));
    end if;

    return jsonb_build_object('success', true, 'new_balance', v_sender_balance - v_gift_price);
exception when others then
    return jsonb_build_object('success', false, 'error', sqlerrm);
end;
$$;

REVOKE ALL ON FUNCTION public.process_gift_purchase(uuid, uuid, uuid, numeric) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.process_gift_purchase(uuid, uuid, uuid, numeric) TO authenticated, service_role;
REVOKE ALL ON FUNCTION public.process_gift_purchase(uuid, uuid, text) FROM public, anon;
GRANT EXECUTE ON FUNCTION public.process_gift_purchase(uuid, uuid, text) TO authenticated, service_role;


-- -----------------------------------------------------------------------------
-- [Migration: 20261021100000_send_coin_gift_notification.sql]
-- -----------------------------------------------------------------------------
-- Migration: 20261021100000_send_coin_gift_notification.sql
-- Description:
-- 1. Updates send_coin_gift RPC to insert an authoritative notification into public.notifications
--    with rich gift metadata (gift_id, gift_name, gift_emoji, gift_coins, earning_credit_ngn, sender_id, sender_name, sender_avatar)
--    so recipient receives real-time TikTok-style gift celebration animation and push notification.
-- 2. Enriches messages.metadata with earning_credit_ngn and sender details.
-- 3. Grants execute on send_coin_gift to authenticated role.

CREATE OR REPLACE FUNCTION public.send_coin_gift(
    p_receiver_id UUID,
    p_gift_id TEXT,
    p_match_id UUID
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_sender_id UUID := auth.uid();
    v_sender_coins INTEGER;
    v_sender_name TEXT;
    v_sender_avatar TEXT;
    v_gift_cost INTEGER;
    v_gift_name TEXT;
    v_gift_emoji TEXT;
    v_gift_color TEXT;
    v_gift_desc TEXT;
    v_earning_credit NUMERIC(12,2);
    v_receiver_wallet_id UUID;
    v_tx_ref TEXT;
    v_msg_id UUID;
    v_notif_priority TEXT := 'high';
BEGIN
    IF v_sender_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Authentication required');
    END IF;

    IF v_sender_id = p_receiver_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'Cannot send gifts to yourself');
    END IF;

    IF EXISTS (
        SELECT 1 FROM public.user_blocks
        WHERE (blocker_id = v_sender_id AND blocked_id = p_receiver_id)
           OR (blocker_id = p_receiver_id AND blocked_id = v_sender_id)
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Communication is blocked with this user');
    END IF;

    -- Fetch sender info
    SELECT full_name, avatar_url, coins INTO v_sender_name, v_sender_avatar, v_sender_coins
    FROM public.profiles
    WHERE id = v_sender_id
    FOR UPDATE;

    CASE p_gift_id
        WHEN 'rose' THEN
            v_gift_cost := 20;
            v_gift_name := 'Digital Rose';
            v_gift_emoji := '🌹';
            v_gift_color := '#f43f5e';
            v_gift_desc := 'A classic romantic gesture';
        WHEN 'zobo' THEN
            v_gift_cost := 20;
            v_gift_name := 'Cold Zobo';
            v_gift_emoji := '🍷';
            v_gift_color := '#9d174d';
            v_gift_desc := 'Chilled campus refreshment';
        WHEN 'suya' THEN
            v_gift_cost := 50;
            v_gift_name := 'Hot Suya';
            v_gift_emoji := '🍢';
            v_gift_color := '#ea580c';
            v_gift_desc := 'Spicy peppered night snack';
        WHEN 'airtime' THEN
            v_gift_cost := 100;
            v_gift_name := 'Airtime Charm';
            v_gift_emoji := '📱';
            v_gift_color := '#2563eb';
            v_gift_desc := 'Keep the conversations buzzing';
        WHEN 'bouquet' THEN
            v_gift_cost := 200;
            v_gift_name := 'Campus Bouquet';
            v_gift_emoji := '💐';
            v_gift_color := '#10b981';
            v_gift_desc := 'Delightful arrangement of blossoms';
        WHEN 'crown' THEN
            v_gift_cost := 500;
            v_gift_name := 'Royal Crown';
            v_gift_emoji := '👑';
            v_gift_color := '#ffd700';
            v_gift_desc := 'Ultimate symbol of campus royalty';
        WHEN 'lion' THEN
            v_gift_cost := 10000;
            v_gift_name := 'Campus Lion';
            v_gift_emoji := '🦁';
            v_gift_color := '#f59e0b';
            v_gift_desc := 'The legendary ₦100k Campus Lion gift';
            v_notif_priority := 'critical';
        ELSE
            RETURN jsonb_build_object('success', false, 'error', 'Unknown gift ID');
    END CASE;

    IF coalesce(v_sender_coins, 0) < v_gift_cost THEN
        RETURN jsonb_build_object('success', false, 'error', 'Insufficient CD Coins. Please recharge your coins.');
    END IF;

    v_tx_ref := 'gift_' || v_sender_id || '_' || extract(epoch from now())::bigint;

    UPDATE public.profiles
    SET coins = coins - v_gift_cost
    WHERE id = v_sender_id
    RETURNING coins INTO v_sender_coins;

    INSERT INTO public.coin_transactions (
        user_id, amount, balance_after, transaction_type, reference, source, destination_user_id, metadata
    ) VALUES (
        v_sender_id, -v_gift_cost, v_sender_coins, 'gift_sent', v_tx_ref, 'gift_store', p_receiver_id,
        jsonb_build_object('gift_id', p_gift_id, 'gift_name', v_gift_name, 'match_id', p_match_id)
    );

    -- 80% split back to student receiver wallet: 10,000 coins * 10 * 0.8 = ₦80,000 credit
    v_earning_credit := (v_gift_cost * 10 * 0.8)::numeric(12,2);
    
    INSERT INTO public.wallets (user_id, available_balance, total_earned)
    VALUES (p_receiver_id, 0, 0)
    ON CONFLICT (user_id) DO NOTHING;

    SELECT id INTO v_receiver_wallet_id
    FROM public.wallets
    WHERE user_id = p_receiver_id;

    IF v_receiver_wallet_id IS NOT NULL THEN
        UPDATE public.wallets
        SET available_balance = available_balance + v_earning_credit,
            total_earned = coalesce(total_earned, 0) + v_earning_credit,
            updated_at = now()
        WHERE id = v_receiver_wallet_id;

        INSERT INTO public.wallet_transactions (
            user_id, wallet_id, type, amount, status, description, metadata
        ) VALUES (
            p_receiver_id, v_receiver_wallet_id, 'gift_received', v_earning_credit, 'completed',
            'Gift received: ' || v_gift_name,
            jsonb_build_object('gift_id', p_gift_id, 'sender_id', v_sender_id, 'gift_coins', v_gift_cost)
        );
    END IF;

    -- Insert in-chat message
    INSERT INTO public.messages (
        match_id, sender_id, content, type, metadata
    ) VALUES (
        p_match_id, v_sender_id, 'Sent ' || v_gift_name || ' ' || v_gift_emoji, 'gift',
        jsonb_build_object(
            'gift_id', p_gift_id,
            'gift_name', v_gift_name,
            'gift_emoji', v_gift_emoji,
            'gift_color', v_gift_color,
            'gift_coins', v_gift_cost,
            'earning_credit_ngn', v_earning_credit,
            'sender_id', v_sender_id,
            'sender_name', coalesce(v_sender_name, 'Someone Special'),
            'sender_avatar', v_sender_avatar
        )
    )
    RETURNING id INTO v_msg_id;

    -- Insert real-time notification for recipient with gift metadata
    BEGIN
        INSERT INTO public.notifications (
            user_id,
            recipient_id,
            actor_id,
            sender_id,
            type,
            category,
            entity_type,
            entity_id,
            match_id,
            title,
            content,
            deep_link,
            priority,
            metadata
        ) VALUES (
            p_receiver_id,
            p_receiver_id,
            v_sender_id,
            v_sender_id,
            'gift_received',
            'messages',
            'message',
            v_msg_id,
            p_match_id,
            coalesce(v_sender_name, 'Someone') || ' sent you ' || v_gift_name || ' ' || v_gift_emoji,
            'You received ' || v_gift_name || ' (' || v_gift_cost || ' coins)! ₦' || v_earning_credit || ' was added to your earnings.',
            '/chat?id=' || p_match_id,
            v_notif_priority,
            jsonb_build_object(
                'gift_id', p_gift_id,
                'gift_name', v_gift_name,
                'gift_emoji', v_gift_emoji,
                'gift_color', v_gift_color,
                'gift_coins', v_gift_cost,
                'earning_credit_ngn', v_earning_credit,
                'sender_id', v_sender_id,
                'sender_name', coalesce(v_sender_name, 'Someone Special'),
                'sender_avatar', v_sender_avatar,
                'match_id', p_match_id,
                'message_id', v_msg_id
            )
        );
    EXCEPTION WHEN OTHERS THEN
        -- Notification insertion defensive fallback
    END;

    RETURN jsonb_build_object(
        'success', true,
        'remaining_coins', v_sender_coins,
        'new_coin_balance', v_sender_coins,
        'gift_name', v_gift_name,
        'gift_emoji', v_gift_emoji,
        'message_id', v_msg_id
    );
END;
$$;

GRANT EXECUTE ON FUNCTION public.send_coin_gift(UUID, TEXT, UUID) TO authenticated;


-- -----------------------------------------------------------------------------
-- [Migration: 20261021110000_add_has_seen_tour_to_profiles.sql]
-- -----------------------------------------------------------------------------
-- Migration: Add has_seen_tour column to public.profiles and backfill existing accounts
-- File: supabase/migrations/20261021110000_add_has_seen_tour_to_profiles.sql

-- 1. Add has_seen_tour column to profiles
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS has_seen_tour boolean DEFAULT false;

-- 2. Backfill existing active and established accounts
-- Accounts created more than 24 hours ago, or with completed profile elements,
-- are experienced members who must not see the introductory tour.
UPDATE public.profiles
SET has_seen_tour = true
WHERE has_seen_tour IS NOT TRUE
  AND (
    created_at < now() - interval '24 hours'
    OR completion_score >= 30
    OR (bio IS NOT NULL AND bio != '')
    OR (avatar_url IS NOT NULL AND avatar_url != '')
    OR is_verified = true
    OR is_optimised = true
  );

-- 3. Document table column
COMMENT ON COLUMN public.profiles.has_seen_tour IS 'Flag indicating whether user has seen or dismissed the introductory onboarding tour';


-- -----------------------------------------------------------------------------
-- [Migration: 20261021120000_fix_campus_finder_user_blocks_table.sql]
-- -----------------------------------------------------------------------------
-- ============================================================================
-- The College Date: Campus Finder (Fix user_blocks relation in discovery RPC)
-- Migration: 20261021120000_fix_campus_finder_user_blocks_table.sql
-- Description: Fix get_eligible_campus_finder_profiles to reference public.user_blocks
--              instead of non-existent public.blocks, and provide a compatibility view.
-- ============================================================================

-- 1. Create a compatibility view for public.blocks pointing to public.user_blocks
-- to ensure any legacy queries or functions will never throw "relation blocks does not exist"
DROP VIEW IF EXISTS public.blocks CASCADE;
CREATE OR REPLACE VIEW public.blocks AS
SELECT * FROM public.user_blocks;

GRANT SELECT, INSERT, UPDATE, DELETE ON public.blocks TO authenticated, service_role;

-- 2. Secure candidate discovery RPC: returns ONLY opted-in, non-blocked candidates
-- referencing the authoritative public.user_blocks table
CREATE OR REPLACE FUNCTION public.get_eligible_campus_finder_profiles(
    p_university text,
    p_exclude_user_id uuid default null
)
RETURNS TABLE (
    id uuid,
    full_name text,
    avatar_url text,
    primary_photo text,
    university text,
    department text,
    level text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
    v_searcher_id uuid;
BEGIN
    v_searcher_id := coalesce(p_exclude_user_id, auth.uid());

    RETURN QUERY
    SELECT 
        p.id,
        p.full_name,
        p.avatar_url,
        coalesce(p.avatar_url, p.profile_photos[1]) as primary_photo,
        p.university,
        p.department,
        p.level
    FROM public.profiles p
    WHERE p.allow_camera_discovery = true
      AND (p_exclude_user_id IS NULL OR p.id != p_exclude_user_id)
      AND (p.university = p_university or p_university is null or p_university = 'All')
      AND (p.is_verified = true or p.photo_verified = true)
      AND NOT EXISTS (
          SELECT 1 FROM public.user_blocks b
          WHERE (b.blocker_id = auth.uid() AND b.blocked_id = p.id)
             OR (b.blocker_id = p.id AND b.blocked_id = auth.uid())
      )
      AND coalesce(p.is_shadow_banned, false) = false
      AND (p.avatar_url is not null or array_length(p.profile_photos, 1) > 0)
    ORDER BY p.last_seen_at desc nulls last
    LIMIT 25;
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_eligible_campus_finder_profiles TO authenticated;

-- 3. Search credit refund helper to restore credits if candidate search or AI service encounters an error
CREATE OR REPLACE FUNCTION public.refund_finder_search(p_searcher_id uuid default null)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
    v_searcher_id uuid;
    v_profile record;
    v_free_left integer;
    v_hourly integer;
BEGIN
    v_searcher_id := coalesce(p_searcher_id, auth.uid());
    if v_searcher_id is null or auth.uid() != v_searcher_id then
        return jsonb_build_object('success', false, 'error', 'Unauthorized');
    end if;

    select * into v_profile
    from public.profiles
    where id = v_searcher_id
    for update;

    if not found then
        return jsonb_build_object('success', false, 'error', 'Profile not found');
    end if;

    v_free_left := least(2, coalesce(v_profile.finder_free_searches_left, 0) + 1);
    v_hourly := greatest(0, coalesce(v_profile.finder_hourly_searches, 1) - 1);

    update public.profiles
    set finder_free_searches_left = v_free_left,
        finder_hourly_searches = v_hourly
    where id = v_searcher_id;

    return jsonb_build_object('success', true, 'free_searches_left', v_free_left);
END;
$$;

GRANT EXECUTE ON FUNCTION public.refund_finder_search TO authenticated;


